/** Get the default {@link BoundaryIOManager3D} instance.
     * @return the default {@link BoundaryIOManager3D} instance
     */

method_definition:
public static BoundaryIOManager3D getDefaultManager() {
        return ManagerHolder.DEFAULT_MANAGER;
    }

@Override
    public List<Vector3D> getVertices() {
        return vertices;
    }

@Override
    public Vector3D getNormal() {
        return normal;
    }

@Override
    public String toString() {
        final StringBuilder sb = new StringBuilder();
        sb.append(getClass().getSimpleName())
            .append("[vertices= ")
            .append(getVertices())
            .append(", normal= ")
            .append(getNormal())
            .append(']');

        return sb.toString();
    }

public static ConvexPolygon3D toPolygon(final Collection<Vector3D> vertices, final Vector3D normal,
            final Precision.DoubleEquivalence precision) {
        final ConvexPolygon3D polygon = Planes.convexPolygonFromVertices(vertices, precision);

        // ensure that the polygon normal matches whatever normal was defined, if any
        if (normal != null &&
                normal.dot(polygon.getPlane().getNormal()) < 0) {
            return polygon.reverse();
        }
        return polygon;
    }

public static ConvexPolygon3D toPolygon(final FacetDefinition facet, final Precision.DoubleEquivalence precision) {
        Objects.requireNonNull(facet, "Facet cannot be null");
        Objects.requireNonNull(precision, "Precision context cannot be null");
        return toPolygon(facet.getVertices(), facet.getNormal(), precision);
    }

@Override
    public BoundarySource3D read(final GeometryInput in, final Precision.DoubleEquivalence precision) {
        // read the input as a simple list of boundaries
        final List<PlaneConvexSubset> list = new ArrayList<>();

        try (FacetDefinitionReader reader = facetDefinitionReader(in)) {
            FacetDefinition facet;
            while ((facet = reader.readFacet()) != null) {
                list.add(FacetDefinitions.toPolygon(facet, precision));
            }
        }

        return new BoundaryList3D(list);
    }

@Override
    public TriangleMesh readTriangleMesh(final GeometryInput in, final Precision.DoubleEquivalence precision) {
        final SimpleTriangleMesh.Builder meshBuilder = SimpleTriangleMesh.builder(precision);

        try (FacetDefinitionReader reader = facetDefinitionReader(in)) {
            FacetDefinition facet;
            while ((facet = reader.readFacet()) != null) {
                for (final Triangle3D tri : FacetDefinitions.toPolygon(facet, precision).toTriangles()) {
                    meshBuilder.addFaceUsingVertices(
                        tri.getPoint1(),
                        tri.getPoint2(),
                        tri.getPoint3()
                    );
                }
            }
        }

        return meshBuilder.build();
    }

@Override
    public Stream<PlaneConvexSubset> boundaries(final GeometryInput in, final Precision.DoubleEquivalence precision) {
        return facets(in)
                .map(f -> FacetDefinitions.toPolygon(f, precision));
    }

@Override
    public Stream<FacetDefinition> facets(final GeometryInput in) {
        return GeometryIOUtils.createCloseableStream(inputStream -> {
            final FacetDefinitionReader fdReader = facetDefinitionReader(in);
            final FacetDefinitionReaderIterator it = new FacetDefinitionReaderIterator(fdReader);

            return StreamSupport.stream(Spliterators.spliteratorUnknownSize(it, Spliterator.ORDERED), false);
        }, in::getInputStream);
    }

@Override
        public boolean hasNext() {
            ensureLoaded();
            return next != null;
        }

@Override
        public FacetDefinition next() {
            if (!hasNext()) {
                throw new NoSuchElementException();
            }

            final FacetDefinition result = next;
            loadNext();

            return result;
        }

docstring:
/** Ensure that the instance has attempted to load at least one facet from
         * the underlying reader.
         */

method_definition:
private void ensureLoaded() {
            if (loadCount < 1) {
                loadNext();
            }
        }

private void loadNext() {
            ++loadCount;
            next = reader.readFacet();
        }

docstring:
/** Write the start of an unnamed STL solid definition. This method is equivalent to calling
     * {@code stlWriter.startSolid(null);}
     * @throws java.io.UncheckedIOException if an I/O error occurs
     */

method_definition:
public void startSolid() {
        startSolid(null);
    }

public void startSolid(final String solidName) {
        if (started) {
            throw new IllegalStateException("Cannot start solid definition: a solid is already being written");
        }
        if (solidName != null && (solidName.indexOf('\r') > -1 || solidName.indexOf('\n') > -1)) {
            throw new IllegalArgumentException("Solid name cannot contain new line characters");
        }

        name = solidName;
        writeBeginOrEndLine(StlConstants.SOLID_START_KEYWORD);

        started = true;
    }

public void endSolid() {
        if (!started) {
            throw new IllegalStateException("Cannot end solid definition: no solid has been started");
        }

        writeBeginOrEndLine(StlConstants.SOLID_END_KEYWORD);
        name = null;
        started = false;
    }

public void writeTriangles(final PlaneConvexSubset boundary) {
        for (final Triangle3D tri : boundary.toTriangles()) {
            writeTriangles(tri.getVertices(), tri.getPlane().getNormal());
        }
    }

public void writeTriangles(final FacetDefinition facet) {
        writeTriangles(facet.getVertices(), facet.getNormal());
    }

public void writeTriangles(final List<Vector3D> vertices, final Vector3D normal) {
        for (final List<Vector3D> triangle : EuclideanUtils.convexPolygonToTriangleFan(vertices, t -> t)) {
            writeTriangle(
                    triangle.get(0),
                    triangle.get(1),
                    triangle.get(2),
                    normal);
        }
    }

public void writeTriangle(final Vector3D p1, final Vector3D p2, final Vector3D p3, final Vector3D normal) {
        if (!started) {
            throw new IllegalStateException("Cannot write triangle: no solid has been started");
        }

        write(StlConstants.FACET_START_KEYWORD);
        write(SPACE);
        writeVector(StlUtils.determineNormal(p1, p2, p3, normal));
        writeNewLine();

        write(StlConstants.OUTER_KEYWORD);
        write(SPACE);
        write(StlConstants.LOOP_START_KEYWORD);
        writeNewLine();

        writeTriangleVertex(p1);

        if (StlUtils.pointsAreCounterClockwise(p1, p2, p3, normal)) {
            writeTriangleVertex(p2);
            writeTriangleVertex(p3);
        } else {
            writeTriangleVertex(p3);
            writeTriangleVertex(p2);
        }

        write(StlConstants.LOOP_END_KEYWORD);
        writeNewLine();

        write(StlConstants.FACET_END_KEYWORD);
        writeNewLine();
    }

@Override
    public void close() {
        if (started) {
            endSolid();
        }

        super.close();
    }

private void writeTriangleVertex(final Vector3D vertex) {
        write(StlConstants.VERTEX_KEYWORD);
        write(SPACE);
        writeVector(vertex);
        writeNewLine();
    }

private void writeVector(final Vector3D vec) {
        write(vec.getX());
        write(SPACE);
        write(vec.getY());
        write(SPACE);
        write(vec.getZ());
    }

private void writeBeginOrEndLine(final String keyword) {
        write(keyword);
        write(SPACE);

        if (name != null) {
            write(name);
        }

        writeNewLine();
    }

public ByteBuffer getHeader() {
        beginRead();
        return ByteBuffer.wrap(header.array().clone());
    }

public String getHeaderAsString() {
        return getHeaderAsString(StlConstants.DEFAULT_CHARSET);
    }

public String getHeaderAsString(final Charset charset) {
        // decode the entire header as characters in the given charset
        final String raw = charset.decode(getHeader()).toString();

        // strip out any control characters, such as '\0'
        final StringBuilder sb = new StringBuilder();
        for (char c : raw.toCharArray()) {
            if (!Character.isISOControl(c)) {
                sb.append(c);
            }
        }

        return sb.toString();
    }

public long getNumTriangles() {
        beginRead();
        return triangleTotal;
    }

@Override
    public BinaryStlFacetDefinition readFacet() {
        beginRead();

        BinaryStlFacetDefinition facet = null;

        if (trianglesRead < triangleTotal) {
            facet = readFacetInternal();

            ++trianglesRead;
        }

        return facet;
    }

@Override
    public void close() {
        GeometryIOUtils.closeUnchecked(in);
    }

private void beginRead() {
        if (!hasReadHeader) {
            // read header content
            final int headerBytesRead = GeometryIOUtils.applyAsIntUnchecked(in::read, header.array());
            if (headerBytesRead < StlConstants.BINARY_HEADER_BYTES) {
                throw dataNotAvailable("header");
            }

            header.rewind();

            // read the triangle total
            final ByteBuffer triangleBuf = StlUtils.byteBuffer(Integer.BYTES);

            if (fill(triangleBuf) < triangleBuf.capacity()) {
                throw dataNotAvailable("triangle count");
            }

            triangleTotal = Integer.toUnsignedLong(triangleBuf.getInt());

            hasReadHeader = true;
        }
    }

docstring:
/** Internal method to read a single facet from the input.
     * @return facet read from the input
     */

method_definition:
private BinaryStlFacetDefinition readFacetInternal() {
        if (fill(triangleBuffer) < triangleBuffer.capacity()) {
            throw dataNotAvailable("triangle at index " + trianglesRead);
        }

        final Vector3D normal = readVector(triangleBuffer);
        final Vector3D p1 = readVector(triangleBuffer);
        final Vector3D p2 = readVector(triangleBuffer);
        final Vector3D p3 = readVector(triangleBuffer);

        final int attr = Short.toUnsignedInt(triangleBuffer.getShort());

        return new BinaryStlFacetDefinition(Arrays.asList(p1, p2, p3), normal, attr);
    }

private int fill(final ByteBuffer buf) {
        int read = GeometryIOUtils.applyAsIntUnchecked(in::read, buf.array());
        buf.rewind();

        return read;
    }

private Vector3D readVector(final ByteBuffer buf) {
        final double x = buf.getFloat();
        final double y = buf.getFloat();
        final double z = buf.getFloat();

        return Vector3D.of(x, y, z);
    }

private static IllegalStateException dataNotAvailable(final String name) {
        return GeometryIOUtils.parseError("Failed to read STL " + name + ": data not available");
    }

public String getSolidName() {
        ensureSolidStarted();

        return solidName;
    }

@Override
    public FacetDefinition readFacet() {
        if (!foundSolidEnd && parser.hasMoreCharacters()) {
            ensureSolidStarted();

            nextWord();

            int choice = parser.chooseIgnoreCase(
                    StlConstants.FACET_START_KEYWORD,
                    StlConstants.SOLID_END_KEYWORD);

            if (choice == 0) {
                return readFacetInternal();
            } else {
                foundSolidEnd = true;
            }
        }

        return null;
    }

@Override
    public void close() {
        GeometryIOUtils.closeUnchecked(reader);
    }

private FacetDefinition readFacetInternal() {
        matchKeyword(StlConstants.NORMAL_KEYWORD);
        final Vector3D normal = readVector();

        matchKeyword(StlConstants.OUTER_KEYWORD);
        matchKeyword(StlConstants.LOOP_START_KEYWORD);

        matchKeyword(StlConstants.VERTEX_KEYWORD);
        final Vector3D p1 = readVector();

        matchKeyword(StlConstants.VERTEX_KEYWORD);
        final Vector3D p2 = readVector();

        matchKeyword(StlConstants.VERTEX_KEYWORD);
        final Vector3D p3 = readVector();

        matchKeyword(StlConstants.LOOP_END_KEYWORD);
        matchKeyword(StlConstants.FACET_END_KEYWORD);

        return new SimpleFacetDefinition(Arrays.asList(p1, p2, p3), normal);
    }

private void ensureSolidStarted() {
        if (!foundSolidStart) {
            beginSolid();

            foundSolidStart = true;
        }
    }

private void beginSolid() {
        matchKeyword(StlConstants.SOLID_START_KEYWORD);

        solidName = trimmedOrNull(parser.nextLine()
                .getCurrentToken());
    }

private void nextWord() {
        parser.discardWhitespace()
            .nextAlphanumeric();
    }

private void matchKeyword(final String keyword) {
        nextWord();
        parser.matchIgnoreCase(keyword);
    }

private Vector3D readVector() {
        final double x = readDouble();
        final double y = readDouble();
        final double z = readDouble();

        return Vector3D.of(x, y, z);
    }

private double readDouble() {
        return parser
                .discardWhitespace()
                .next(SimpleTextParser::isDecimalPart)
                .getCurrentTokenAsDouble();
    }

private static String trimmedOrNull(final String str) {
        if (str != null) {
            final String trimmed = str.trim();
            if (!trimmed.isEmpty()) {
                return trimmed;
            }
        }

        return null;
    }

@Override
    public GeometryFormat getFormat() {
        return GeometryFormat3D.STL;
    }

public int getinitialBufferSize() {
        return initialBufferSize;
    }

public void setInitialBufferSize(final int initialBufferSize) {
        if (initialBufferSize < 1) {
            throw new IllegalArgumentException("Buffer size must be greater than 0");
        }
        this.initialBufferSize = initialBufferSize;
    }

@Override
    public void write(final BoundarySource3D src, final GeometryOutput out) {
        // handle cases where we know the number of triangles to be written up front
        // and do not need to buffer the content
        if (src instanceof TriangleMesh) {
            writeTriangleMesh((TriangleMesh) src, out);
        } else {
            // unknown number of triangles; proceed with a buffered write
            super.write(src, out);
        }
    }

@Override
    public void write(final Stream<? extends PlaneConvexSubset> boundaries, final GeometryOutput out) {

        // write the triangle data to a buffer and track how many we write
        int triangleCount = 0;
        final ByteArrayOutputStream triangleBuffer = new ByteArrayOutputStream(initialBufferSize);

        try (BinaryStlWriter stlWriter = new BinaryStlWriter(triangleBuffer)) {
            final Iterator<? extends PlaneConvexSubset> it = boundaries.iterator();

            while (it.hasNext()) {
                for (final Triangle3D tri : it.next().toTriangles()) {

                    stlWriter.writeTriangle(
                            tri.getPoint1(),
                            tri.getPoint2(),
                            tri.getPoint3(),
                            tri.getPlane().getNormal());

                    ++triangleCount;
                }
            }
        }

        // write the header and copy the data
        writeWithHeader(triangleBuffer, triangleCount, out);
    }

@Override
    public void writeFacets(final Stream<? extends FacetDefinition> facets, final GeometryOutput out) {

        // write the triangle data to a buffer and track how many we write
        int triangleCount = 0;
        final ByteArrayOutputStream triangleBuffer = new ByteArrayOutputStream(initialBufferSize);

        try (BinaryStlWriter dataWriter = new BinaryStlWriter(triangleBuffer)) {
            final Iterator<? extends FacetDefinition> it = facets.iterator();

            FacetDefinition facet;
            int attributeValue;

            while (it.hasNext()) {
                facet = it.next();
                attributeValue = getFacetAttributeValue(facet);

                for (final List<Vector3D> tri :
                    EuclideanUtils.convexPolygonToTriangleFan(facet.getVertices(), t -> t)) {

                    dataWriter.writeTriangle(
                            tri.get(0),
                            tri.get(1),
                            tri.get(2),
                            facet.getNormal(),
                            attributeValue);

                    ++triangleCount;
                }
            }
        }

        // write the header and copy the data
        writeWithHeader(triangleBuffer, triangleCount, out);
    }

docstring:
/** Write the given triangle data prefixed with an STL header to the output stream from {@code out}.
     * @param triangleBuffer buffer containing STL triangle data
     * @param count number of triangles in {@code triangleBuffer}
     * @param out output to write to
     * @throws java.io.UncheckedIOException if an I/O error occurs
     */

method_definition:
private void writeWithHeader(final ByteArrayOutputStream triangleBuffer, final int count,
            final GeometryOutput out) {
        // write the header and copy the data
        try (OutputStream os = out.getOutputStream()) {
            BinaryStlWriter.writeHeader(null, count, os);
            triangleBuffer.writeTo(os);
        } catch (IOException exc) {
            throw GeometryIOUtils.createUnchecked(exc);
        }
    }

private void writeTriangleMesh(final TriangleMesh mesh, final GeometryOutput output) {
        try (BinaryStlWriter stlWriter = new BinaryStlWriter(output.getOutputStream())) {
            // write the header
            stlWriter.writeHeader(null, mesh.getFaceCount());

            // write each triangle
            Triangle3D tri;
            for (final TriangleMesh.Face face : mesh.faces()) {
                tri = face.getPolygon();

                stlWriter.writeTriangle(
                        tri.getPoint1(),
                        tri.getPoint2(),
                        tri.getPoint3(),
                        tri.getPlane().getNormal());
            }
        }
    }

private int getFacetAttributeValue(final FacetDefinition facet) {
        if (facet instanceof BinaryStlFacetDefinition) {
            return ((BinaryStlFacetDefinition) facet).getAttributeValue();
        }

        return 0;
    }

public int getAttributeValue() {
        return attributeValue;
    }

static ByteBuffer byteBuffer(final int capacity) {
        return ByteBuffer.allocate(capacity)
                .order(StlConstants.BINARY_BYTE_ORDER);
    }

static Vector3D determineNormal(final Vector3D p1, final Vector3D p2, final Vector3D p3,
            final Vector3D normal) {
        if (normal != null) {
            // try to normalize it
            final Vector3D normalized = normal.normalizeOrNull();
            if (normalized != null) {
                return normalized;
            }
        }

        // try to compute one from the triangle points
        final Vector3D computed = computeTriangleNormal(p1, p2, p3);
        return computed != null ?
                computed :
                Vector3D.ZERO;
    }

static boolean pointsAreCounterClockwise(final Vector3D p1, final Vector3D p2, final Vector3D p3,
            final Vector3D normal) {
        if (normal != null) {
            final Vector3D computedNormal = computeTriangleNormal(p1, p2, p3);
            if (computedNormal != null && normal.dot(computedNormal) < 0) {
                return false;
            }
        }

        return true;
    }

private static Vector3D computeTriangleNormal(final Vector3D p1, final Vector3D p2, final Vector3D p3) {
        final Vector3D normal = p1.vectorTo(p2).cross(p1.vectorTo(p3)).normalizeOrNull();
        return normal != null ?
                normal :
                null;
    }

public void writeHeader(final byte[] headerContent, final int triangleCount) {
        writeHeader(headerContent, triangleCount, out);
    }

public void writeTriangle(final Vector3D p1, final Vector3D p2, final Vector3D p3,
            final Vector3D normal) {
        writeTriangle(p1, p2, p3, normal, 0);
    }

public void writeTriangle(final Vector3D p1, final Vector3D p2, final Vector3D p3,
            final Vector3D normal, final int attributeValue) {
        triangleBuffer.rewind();

        putVector(StlUtils.determineNormal(p1, p2, p3, normal));
        putVector(p1);

        if (StlUtils.pointsAreCounterClockwise(p1, p2, p3, normal)) {
            putVector(p2);
            putVector(p3);
        } else {
            putVector(p3);
            putVector(p2);
        }

        triangleBuffer.putShort((short) attributeValue);

        GeometryIOUtils.acceptUnchecked(out::write, triangleBuffer.array());
    }

@Override
    public void close() {
        GeometryIOUtils.closeUnchecked(out);
    }

docstring:
/** Put all double components of {@code vec} into the internal buffer.
     * @param vec vector to place into the buffer
     */

method_definition:
private void putVector(final Vector3D vec) {
        triangleBuffer.putFloat((float) vec.getX());
        triangleBuffer.putFloat((float) vec.getY());
        triangleBuffer.putFloat((float) vec.getZ());
    }

static void writeHeader(final byte[] headerContent, final int triangleCount, final OutputStream out) {
        // write the header
        final byte[] bytes = new byte[StlConstants.BINARY_HEADER_BYTES];
        if (headerContent != null) {
            System.arraycopy(
                    headerContent, 0,
                    bytes, 0,
                    Math.min(headerContent.length, StlConstants.BINARY_HEADER_BYTES));
        }

        GeometryIOUtils.acceptUnchecked(out::write, bytes);

        // write the triangle count number
        ByteBuffer countBuffer = StlUtils.byteBuffer(Integer.BYTES);
        countBuffer.putInt(triangleCount);
        countBuffer.flip();

        GeometryIOUtils.acceptUnchecked(out::write, countBuffer.array());
    }

public static FacetDefinitionReader create(final InputStream in, final Charset charset) {
        final Charset inputCharset = charset != null ?
                charset :
                StlConstants.DEFAULT_CHARSET;

        final byte[] testBytes = StlConstants.SOLID_START_KEYWORD.getBytes(inputCharset);
        final byte[] actualBytes = new byte[testBytes.length];

        final int read = GeometryIOUtils.applyAsIntUnchecked(in::read, actualBytes);
        if (read < actualBytes.length) {
            throw GeometryIOUtils.parseError(MessageFormat.format(
                    "Cannot determine STL format: attempted to read {0} bytes but found only {1} available",
                    actualBytes.length, read));
        }

        // "unread" the test bytes so that the created readers can start from the
        // beginning of the content
        final PushbackInputStream pushbackInput = new PushbackInputStream(in, actualBytes.length);
        GeometryIOUtils.acceptUnchecked(pushbackInput::unread, actualBytes);

        if (Arrays.equals(testBytes, actualBytes)) {
            // this is a text file
            return new TextStlFacetDefinitionReader(
                    new BufferedReader(new InputStreamReader(pushbackInput, inputCharset)));
        } else {
            // this is a binary file
            return new BinaryStlFacetDefinitionReader(pushbackInput);
        }
    }

