            return arc.getEndPoint() != null;
        }

@Override
        public boolean endPointsEq(final ConnectableGreatArc other) {
            if (hasEnd() && other.hasEnd()) {
                return arc.getEndPoint()
                        .eq(other.arc.getEndPoint(), arc.getCircle().getPrecision());
            }

            return false;
