public <T> T parse(final String str, final DoubleFunction1N<T> fn) {
        final ParsePosition pos = new ParsePosition(0);

        readPrefix(str, pos);
        final double v = readTupleValue(str, pos);
        readSuffix(str, pos);
        endParse(str, pos);

        return fn.apply(v);
    }

public <T> T parse(final String str, final DoubleFunction2N<T> fn) {
        final ParsePosition pos = new ParsePosition(0);

        readPrefix(str, pos);
        final double v1 = readTupleValue(str, pos);
        final double v2 = readTupleValue(str, pos);
        readSuffix(str, pos);
        endParse(str, pos);

        return fn.apply(v1, v2);
    }

public <T> T parse(final String str, final DoubleFunction3N<T> fn) {
        final ParsePosition pos = new ParsePosition(0);

        readPrefix(str, pos);
        final double v1 = readTupleValue(str, pos);
        final double v2 = readTupleValue(str, pos);
        final double v3 = readTupleValue(str, pos);
        readSuffix(str, pos);
        endParse(str, pos);

        return fn.apply(v1, v2, v3);
    }

private void readPrefix(final String str, final ParsePosition pos) {
        if (prefix != null) {
            consumeWhitespace(str, pos);
            readSequence(str, prefix, pos);
        }
    }

private double readTupleValue(final String str, final ParsePosition pos) {
        final int startIdx = pos.getIndex();

        int endIdx = str.indexOf(separator, startIdx);
        if (endIdx < 0) {
            if (suffix != null) {
                endIdx = str.indexOf(suffix, startIdx);
            }

            if (endIdx < 0) {
                endIdx = str.length();
            }
        }

        final String substr = str.substring(startIdx, endIdx);
        try {
            final double value = Double.parseDouble(substr);

            // advance the position and move past any terminating separator
            pos.setIndex(endIdx);
            matchSequence(str, separator, pos);

            return value;
        } catch (final NumberFormatException exc) {
            throw parseFailure(String.format("unable to parse number from string \"%s\"", substr), str, pos, exc);
        }
    }

private void readSuffix(final String str, final ParsePosition pos) {
        if (suffix != null) {
            consumeWhitespace(str, pos);
            readSequence(str, suffix, pos);
        }
    }

private void endParse(final String str, final ParsePosition pos) {
        consumeWhitespace(str, pos);
        if (pos.getIndex() != str.length()) {
            throw parseFailure("unexpected content", str, pos);
        }
    }

private void consumeWhitespace(final String str, final ParsePosition pos) {
        int idx = pos.getIndex();
        final int len = str.length();

        for (; idx < len; ++idx) {
            if (!Character.isWhitespace(str.codePointAt(idx))) {
                break;
            }
        }

        pos.setIndex(idx);
    }

docstring:
/** Return a boolean indicating whether or not the input string {@code str}
     * contains the string {@code seq} at the given parse index. If the match succeeds,
     * the index of {@code pos} is moved to the first character after the match. If
     * the match does not succeed, the parse position is left unchanged.
     * @param str the string to match against
     * @param seq the sequence to look for in {@code str}
     * @param pos the parse position indicating the index in {@code str}
     *      to attempt the match
     * @return true if {@code str} contains exactly the same characters as {@code seq}
     *      at {@code pos}; otherwise, false
     */

method_definition:
private boolean matchSequence(final String str, final String seq, final ParsePosition pos) {
        final int idx = pos.getIndex();
        final int inputLength = str.length();
        final int seqLength = seq.length();

        int i = idx;
        int s = 0;
        for (; i < inputLength && s < seqLength; ++i, ++s) {
            if (str.codePointAt(i) != seq.codePointAt(s)) {
                break;
            }
        }

        if (i <= inputLength && s == seqLength) {
            pos.setIndex(idx + seqLength);
            return true;
        }
        return false;
    }

docstring:
/** Read the string given by {@code seq} from the given position in {@code str}.
     * Throws an IllegalArgumentException if the sequence is not found at that position.
     * @param str the string to match against
     * @param seq the sequence to look for in {@code str}
     * @param pos the parse position indicating the index in {@code str}
     *      to attempt the match
     * @throws IllegalArgumentException if {@code str} does not contain the characters from
     *      {@code seq} at position {@code pos}
     */

method_definition:
private void readSequence(final String str, final String seq, final ParsePosition pos) {
        if (!matchSequence(str, seq, pos)) {
            final int idx = pos.getIndex();
            final String actualSeq = str.substring(idx, Math.min(str.length(), idx + seq.length()));

            throw parseFailure(String.format("expected \"%s\" but found \"%s\"", seq, actualSeq), str, pos);
        }
    }

public static SimpleTupleFormat getDefault() {
        return DEFAULT_INSTANCE;
    }

private static IllegalArgumentException parseFailure(final String msg, final String str, final ParsePosition pos) {
        return parseFailure(msg, str, pos, null);
    }

private static IllegalArgumentException parseFailure(final String msg, final String str, final ParsePosition pos,
                                                         final Throwable cause) {
        final String fullMsg = String.format("Failed to parse string \"%s\" at index %d: %s",
                str, pos.getIndex(), msg);

        return new TupleParseException(fullMsg, cause);
    }

public static <
        P extends Point<P>,
        S extends Point<S>,
        H extends EmbeddingHyperplane<P, S>,
        R extends Region<S>> RegionLocation classifyAgainstEmbeddedRegion(final P pt,
                final H hyperplane, final R embeddedRegion) {

        if (hyperplane.contains(pt)) {
            final S subPoint = hyperplane.toSubspace(pt);

            return embeddedRegion.classify(subPoint);
        }

        return RegionLocation.OUTSIDE;
    }

public static <
        P extends Point<P>,
        S extends Point<S>,
        H extends EmbeddingHyperplane<P, S>,
        R extends Region<S>> P closestToEmbeddedRegion(final P pt,
                final H hyperplane, final R embeddedRegion) {

        final S subPt = hyperplane.toSubspace(pt);

        if (embeddedRegion.contains(subPt)) {
            return hyperplane.toSpace(subPt);
        }

        final S subProjected = embeddedRegion.project(subPt);
        if (subProjected != null) {
            return hyperplane.toSpace(subProjected);
        }

        return null;
    }

docstring:
/** Set the tree used as output for this instance.
     * @param outputTree the tree used as output for this instance
     */

method_definition:
protected void setOutputTree(final AbstractBSPTree<P, N> outputTree) {
        this.outputTree = outputTree;
    }

docstring:
/** Get the tree used as output for this instance.
     * @return the tree used as output for this instance
     */

method_definition:
protected AbstractBSPTree<P, N> getOutputTree() {
        return outputTree;
    }

protected void performMerge(final AbstractBSPTree<P, N> input1, final AbstractBSPTree<P, N> input2,
            final AbstractBSPTree<P, N> output) {

        setOutputTree(output);

        final N root1 = input1.getRoot();
        final N root2 = input2.getRoot();

        final N outputRoot = performMergeRecursive(root1, root2);

        getOutputTree().setRoot(outputRoot);
    }

private N performMergeRecursive(final N node1, final N node2) {

        if (node1.isLeaf() || node2.isLeaf()) {
            // delegate to the mergeLeaf method if we can no longer continue
            // merging recursively
            final N merged = mergeLeaf(node1, node2);

            // copy the merged node to the output if needed (in case mergeLeaf
            // returned one of the input nodes directly)
            return outputTree.importSubtree(merged);
        } else {
            final N partitioned = outputTree.splitSubtree(node2, node1.getCut());

            final N minus = performMergeRecursive(node1.getMinus(), partitioned.getMinus());

            final N plus = performMergeRecursive(node1.getPlus(), partitioned.getPlus());

            final N outputNode = outputTree.copyNode(node1);
            outputNode.setSubtree(node1.getCut(), minus, plus);

            return outputNode;
        }
    }

protected N outputNode() {
        return outputTree.createNode();
    }

protected N outputSubtree(final N node) {
        return outputTree.importSubtree(node);
    }

public List<HyperplaneConvexSubset<P>> getInsideFacing() {
        return insideFacing;
    }

public List<HyperplaneConvexSubset<P>> getOutsideFacing() {
        return outsideFacing;
    }

docstring:
/** Get the total size of the cut boundary, including inside and outside facing components.
     * @return the total size of the cut boundary, including inside and outside facing components
     */

method_definition:
@Override
    public double getSize() {
        return getTotalSize(insideFacing) + getTotalSize(outsideFacing);
    }

private double getTotalSize(final List<? extends HyperplaneConvexSubset<P>> boundaries) {
        double total = 0.0;
        for (final HyperplaneConvexSubset<P> boundary : boundaries) {
            total += boundary.getSize();

            if (Double.isInfinite(total)) {
                return total;
            }
        }

        return total;
    }

public P closest(final P pt) {
        P closest = null;
        double closestDist = Double.POSITIVE_INFINITY;

        final Iterator<HyperplaneConvexSubset<P>> insideIt = insideFacing.iterator();
        final Iterator<HyperplaneConvexSubset<P>> outsideIt = outsideFacing.iterator();

        HyperplaneConvexSubset<P> boundary;
        P testPt;
        double dist;

        while (insideIt.hasNext() || outsideIt.hasNext()) {
            boundary = insideIt.hasNext() ?
                    insideIt.next() :
                    outsideIt.next();

            testPt = boundary.closest(pt);
            dist = pt.distance(testPt);

            if (closest == null || dist < closestDist) {
                closest = testPt;
                closestDist = dist;
            }
        }

        return closest;
    }

public boolean contains(final P pt) {
        return containsInsideFacing(pt) || containsOutsideFacing(pt);
    }

public boolean containsInsideFacing(final P pt) {
        return anyContains(pt, insideFacing);
    }

public boolean containsOutsideFacing(final P pt) {
        return anyContains(pt, outsideFacing);
    }

private boolean anyContains(final P pt, final List<? extends HyperplaneConvexSubset<P>> boundaries) {
        for (final HyperplaneConvexSubset<P> boundary : boundaries) {
            if (boundary.contains(pt)) {
                return true;
            }
        }

        return false;
    }

docstring:
/** Internal method to build and return the tree representing the final partitioned region.
     * @return the partitioned region
     */

method_definition:
protected AbstractRegionBSPTree<P, N> buildInternal() {
        // condense to combine homogenous leaf nodes
        tree.condense();

        // propagate region interiors to partitioned nodes that have not received
        // a boundary
        if (propagateRegionInterior()) {
            // condense again since some leaf nodes changed
            tree.condense();
        }

        return tree;
    }

protected void insertPartitionInternal(final HyperplaneConvexSubset<P> partition) {
        ensureInsertingPartitions();

        tree.insert(partition, RegionCutRule.INHERIT);
    }

docstring:
/** Internal method to insert a region boundary into the tree.
     * @param boundary boundary to insert
     */

method_definition:
protected void insertBoundaryInternal(final HyperplaneConvexSubset<P> boundary) {
        if (insertingPartitions) {
            // switch to inserting boundaries; place all current internal nodes into
            // a set for easy identification
            for (final N node : tree.nodes()) {
                if (node.isInternal()) {
                    partitionNodes.add(node);
                }
            }

            insertingPartitions = false;
        }

        insertBoundaryRecursive(tree.getRoot(), boundary, boundary.getHyperplane().span(),
            (leaf, cut) -> tree.setNodeCut(leaf, cut, subtreeInit));
    }

docstring:
/** Insert a region boundary into the tree.
     * @param node node to insert into
     * @param insert the hyperplane convex subset to insert
     * @param trimmed version of the hyperplane convex subset filling the entire space of {@code node}
     * @param leafFn function to apply to leaf nodes
     */

method_definition:
private void insertBoundaryRecursive(final N node, final HyperplaneConvexSubset<P> insert,
            final HyperplaneConvexSubset<P> trimmed, final BiConsumer<N, HyperplaneConvexSubset<P>> leafFn) {
        if (node.isLeaf()) {
            leafFn.accept(node, trimmed);
        } else {
            insertBoundaryRecursiveInternalNode(node, insert, trimmed, leafFn);
        }
    }

private void insertBoundaryRecursiveInternalNode(final N node, final HyperplaneConvexSubset<P> insert,
            final HyperplaneConvexSubset<P> trimmed, final BiConsumer<N, HyperplaneConvexSubset<P>> leafFn) {

        final Split<? extends HyperplaneConvexSubset<P>> insertSplit =
                insert.split(node.getCutHyperplane());

        final HyperplaneConvexSubset<P> minus = insertSplit.getMinus();
        final HyperplaneConvexSubset<P> plus = insertSplit.getPlus();

        if (minus == null && plus == null && isPartitionNode(node)) {
            // the inserted boundary lies directly on a partition; proceed down the tree with the
            // rest of the insertion algorithm but instead of cutting the final leaf nodes, just
            // set the location

            // remove this node from the set of partition nodes since this is now a boundary cut
            partitionNodes.remove(node);

            final boolean sameOrientation = node.getCutHyperplane().similarOrientation(insert.getHyperplane());
            final N insertMinus = sameOrientation ? node.getMinus() : node.getPlus();
            final N insertPlus = sameOrientation ? node.getPlus() : node.getMinus();

            insertBoundaryRecursive(insertMinus, insert, trimmed,
                (leaf, cut) -> leaf.setLocation(RegionLocation.INSIDE));

            insertBoundaryRecursive(insertPlus, insert, trimmed,
                (leaf, cut) -> leaf.setLocation(RegionLocation.OUTSIDE));

        } else if (minus != null || plus != null) {
            final Split<? extends HyperplaneConvexSubset<P>> trimmedSplit =
                    trimmed.split(node.getCutHyperplane());

            final HyperplaneConvexSubset<P> trimmedMinus = trimmedSplit.getMinus();
            final HyperplaneConvexSubset<P> trimmedPlus = trimmedSplit.getPlus();

            if (minus != null) {
                insertBoundaryRecursive(node.getMinus(), minus, trimmedMinus, leafFn);
            }
            if (plus != null) {
                insertBoundaryRecursive(node.getPlus(), plus, trimmedPlus, leafFn);
            }
        }
    }

private boolean propagateRegionInterior() {
        final List<N> outsidePartitionedLeaves = getOutsidePartitionedLeaves();
        outsidePartitionedLeaves.sort(DEEPEST_FIRST_ORDER);

        int changeCount = 0;

        N parent;
        N sibling;
        for (final N leaf : outsidePartitionedLeaves) {
            parent = leaf.getParent();

            // check if the parent cut touches the inside anywhere on the side opposite of
            // this leaf; if so, then this node should also be inside
            sibling = leaf.isMinus() ?
                    parent.getPlus() :
                    parent.getMinus();

            if (touchesInside(parent.getCut(), sibling)) {
                leaf.setLocation(RegionLocation.INSIDE);

                ++changeCount;
            }
        }

        return changeCount > 0;
    }

docstring:
/** Return a list containing all outside leaf nodes that have a parent marked as a partition node.
     * @return a list containing all outside leaf nodes that have a parent marked as a partition node
     */

method_definition:
private List<N> getOutsidePartitionedLeaves() {
        final List<N> result = new ArrayList<>();

        final N root = tree.getRoot();
        collectOutsidePartitionedLeavesRecursive(root, false, result);

        return result;
    }

private void collectOutsidePartitionedLeavesRecursive(final N node, final boolean parentIsPartitionNode,
            final List<N> result) {
        if (node != null) {
            if (parentIsPartitionNode && node.isOutside()) {
                result.add(node);
            }

            final boolean partitionNode = isPartitionNode(node);

            collectOutsidePartitionedLeavesRecursive(node.getMinus(), partitionNode, result);
            collectOutsidePartitionedLeavesRecursive(node.getPlus(), partitionNode, result);
        }
    }

docstring:
/** Return true if {@code sub} touches an inside leaf node anywhere in the subtree rooted at {@code node}.
     * @param sub convex subset to check
     * @param node root node of the subtree to test against
     * @return true if {@code sub} touches an inside leaf node anywhere in the subtree rooted at {@code node}
     */

method_definition:
private boolean touchesInside(final HyperplaneConvexSubset<P> sub, final N node) {
        if (sub != null) {
            if (node.isLeaf()) {
                return node.isInside();
            } else {
                final Split<? extends HyperplaneConvexSubset<P>> split = sub.split(node.getCutHyperplane());

                return touchesInside(split.getMinus(), node.getMinus()) ||
                        touchesInside(split.getPlus(), node.getPlus());

            }
        }

        return false;
    }

private boolean isPartitionNode(final N node) {
        return partitionNodes.contains(node);
    }

docstring:
/** Throw an exception if the instance is no longer accepting partitions.
     * @throws IllegalStateException if the instance is no longer accepting partitions
     */

method_definition:
private void ensureInsertingPartitions() {
        if (!insertingPartitions) {
            throw new IllegalStateException("Cannot insert partitions after boundaries have been inserted");
        }
    }

default N findNode(final P pt) {
        return findNode(pt, FindNodeCutRule.MINUS);
    }

default Order visitOrder(final N internalNode) {
        return Order.NODE_MINUS_PLUS;
    }

