method_definition:
public static RegionBSPTree3D empty() {
        return new RegionBSPTree3D(false);
    }

public static RegionBSPTree3D from(final Iterable<? extends PlaneConvexSubset> boundaries) {
        return from(boundaries, false);
    }

public static RegionBSPTree3D from(final Iterable<? extends PlaneConvexSubset> boundaries, final boolean full) {
        final RegionBSPTree3D tree = new RegionBSPTree3D(full);
        tree.insert(boundaries);

        return tree;
    }

public static PartitionedRegionBuilder3D partitionedRegionBuilder() {
        return new PartitionedRegionBuilder3D();
    }

public ConvexVolume getNodeRegion() {
            ConvexVolume volume = ConvexVolume.full();

            RegionNode3D child = this;
            RegionNode3D parent;

            while ((parent = child.getParent()) != null) {
                final Split<ConvexVolume> split = volume.split(parent.getCutHyperplane());

                volume = child.isMinus() ? split.getMinus() : split.getPlus();

                child = parent;
            }

            return volume;
        }

@Override
        protected RegionNode3D getSelf() {
            return this;
        }

public PartitionedRegionBuilder3D insertPartition(final Plane partition) {
            return insertPartition(partition.span());
        }

public PartitionedRegionBuilder3D insertPartition(final PlaneConvexSubset partition) {
            insertPartitionInternal(partition);

            return this;
        }

public PartitionedRegionBuilder3D insertAxisAlignedPartitions(final Vector3D center,
                final Precision.DoubleEquivalence precision) {

            insertPartition(Planes.fromPointAndNormal(center, Vector3D.Unit.PLUS_X, precision));
            insertPartition(Planes.fromPointAndNormal(center, Vector3D.Unit.PLUS_Y, precision));
            insertPartition(Planes.fromPointAndNormal(center, Vector3D.Unit.PLUS_Z, precision));

            return this;
        }

public PartitionedRegionBuilder3D insertAxisAlignedGrid(final Bounds3D bounds, final int level,
                final Precision.DoubleEquivalence precision) {

            insertAxisAlignedGridRecursive(bounds.getMin(), bounds.getMax(), level, precision);

            return this;
        }

private void insertAxisAlignedGridRecursive(final Vector3D min, final Vector3D max, final int level,
                final Precision.DoubleEquivalence precision) {
            if (level > 0) {
                final Vector3D center = min.lerp(max, 0.5);

                insertAxisAlignedPartitions(center, precision);

                final int nextLevel = level - 1;
                insertAxisAlignedGridRecursive(min, center, nextLevel, precision);
                insertAxisAlignedGridRecursive(center, max, nextLevel, precision);
            }
        }

public PartitionedRegionBuilder3D insertBoundary(final PlaneConvexSubset boundary) {
            insertBoundaryInternal(boundary);

            return this;
        }

public PartitionedRegionBuilder3D insertBoundaries(final Iterable<? extends PlaneConvexSubset> boundaries) {
            for (final PlaneConvexSubset boundary : boundaries) {
                insertBoundaryInternal(boundary);
            }

            return this;
        }

public PartitionedRegionBuilder3D insertBoundaries(final BoundarySource3D boundarySrc) {
            try (Stream<PlaneConvexSubset> stream = boundarySrc.boundaryStream()) {
                stream.forEach(this::insertBoundaryInternal);
            }

            return this;
        }

docstring:
/** Build and return the region BSP tree.
         * @return the region BSP tree
         */

method_definition:
public RegionBSPTree3D build() {
            return (RegionBSPTree3D) buildInternal();
        }

@Override
        protected Vector3D disambiguateClosestPoint(final Vector3D target, final Vector3D a, final Vector3D b) {
            // return the point with the smallest coordinate values
            final int cmp = Vector3D.COORDINATE_ASCENDING_ORDER.compare(a, b);
            return cmp < 0 ? a : b;
        }

@Override
        public Result visit(final RegionNode3D node) {
            if (node.isInternal()) {
                final RegionCutBoundary<Vector3D> boundary = node.getCutBoundary();

                for (final HyperplaneConvexSubset<Vector3D> outsideFacing : boundary.getOutsideFacing()) {
                    addBoundaryContribution(outsideFacing, false);
                }

                for (final HyperplaneConvexSubset<Vector3D> insideFacing : boundary.getInsideFacing()) {
                    addBoundaryContribution(insideFacing, true);
                }
            }

            return Result.CONTINUE;
        }

docstring:
/** Return the computed size properties for the visited region.
         * @return the computed size properties for the visited region.
         */

method_definition:
public RegionSizeProperties<Vector3D> getRegionSizeProperties() {
            double size = Double.POSITIVE_INFINITY;
            Vector3D centroid = null;

            // we only have a finite size if the volume sum is finite and positive
            // (negative indicates a finite outside surrounded by an infinite inside)
            if (Double.isFinite(volumeSum) && volumeSum > 0.0) {
                // apply the 1/3 pyramid volume scaling factor
                size = volumeSum / 3.0;

                // Since the volume we used when adding together the boundary contributions
                // was 3x the actual pyramid size, we'll multiply by 1/4 here instead
                // of 3/4 to adjust for the actual centroid position in each pyramid.
                final double centroidScale = 1.0 / (4 * size);
                centroid =  Vector3D.of(
                        sumX * centroidScale,
                        sumY * centroidScale,
                        sumZ * centroidScale);
            }

            return new RegionSizeProperties<>(size, centroid);
        }

private void addBoundaryContribution(final HyperplaneSubset<Vector3D> boundary, final boolean reverse) {
            final PlaneSubset boundarySubset = (PlaneSubset) boundary;

            final Plane boundaryPlane = boundarySubset.getPlane();
            final double boundaryArea = boundarySubset.getSize();
            final Vector3D boundaryCentroid = boundarySubset.getCentroid();

            if (Double.isInfinite(boundaryArea)) {
                volumeSum = Double.POSITIVE_INFINITY;
            } else if (boundaryCentroid != null) {
                // the volume here is actually 3x the actual pyramid volume; we'll apply
                // the final scaling all at once at the end
                double scaledVolume = boundaryArea * boundaryCentroid.dot(boundaryPlane.getNormal());
                if (reverse) {
                    scaledVolume = -scaledVolume;
                }

                volumeSum += scaledVolume;

                sumX += scaledVolume * boundaryCentroid.getX();
                sumY += scaledVolume * boundaryCentroid.getY();
                sumZ += scaledVolume * boundaryCentroid.getZ();
            }
        }

docstring:
/** Get the first {@link org.apache.commons.geometry.euclidean.twod.LinecastPoint2D}
         * resulting from the linecast operation.
         * @return the first linecast result point
         */

method_definition:
public LinecastPoint3D getFirstResult() {
            final List<LinecastPoint3D> sortedResults = getResults();

            return sortedResults.isEmpty() ?
                    null :
                    sortedResults.get(0);
        }

public List<LinecastPoint3D> getResults() {
            LinecastPoint3D.sortAndFilter(results);

            return results;
        }

@Override
        public Order visitOrder(final RegionNode3D internalNode) {
            final Plane cut = (Plane) internalNode.getCutHyperplane();
            final Line3D line = linecastSubset.getLine();

            final boolean plusIsNear = line.getDirection().dot(cut.getNormal()) < 0;

            return plusIsNear ?
                    Order.PLUS_NODE_MINUS :
                    Order.MINUS_NODE_PLUS;
        }

@Override
        public Result visit(final RegionNode3D node) {
            if (node.isInternal()) {
                // check if the line subset intersects the node cut hyperplane
                final Line3D line = linecastSubset.getLine();
                final Vector3D pt = ((Plane) node.getCutHyperplane()).intersection(line);

                if (pt != null) {
                    if (firstOnly && !results.isEmpty() &&
                            line.getPrecision().compare(minAbscissa, line.abscissa(pt)) < 0) {
                        // we have results and we are now sure that no other intersection points will be
                        // found that are closer or at the same position on the intersecting line.
                        return Result.TERMINATE;
                    } else if (linecastSubset.contains(pt)) {
                        // we've potentially found a new linecast point; add it to the list of potential
                        // results
                        final LinecastPoint3D potentialResult = computeLinecastPoint(pt, node);
                        if (potentialResult != null) {
                            results.add(potentialResult);

                            // update the min abscissa
                            minAbscissa = Math.min(minAbscissa, potentialResult.getAbscissa());
                        }
                    }
                }
            }

            return Result.CONTINUE;
        }

private LinecastPoint3D computeLinecastPoint(final Vector3D pt, final RegionNode3D node) {
            final Plane cut = (Plane) node.getCutHyperplane();
            final RegionCutBoundary<Vector3D> boundary = node.getCutBoundary();

            boolean onBoundary = false;
            boolean negateNormal = false;

            if (boundary.containsInsideFacing(pt)) {
                // on inside-facing boundary
                onBoundary = true;
                negateNormal = true;
            } else  if (boundary.containsOutsideFacing(pt)) {
                // on outside-facing boundary
                onBoundary = true;
            }

            if (onBoundary) {
                Vector3D normal = cut.getNormal();
                if (negateNormal) {
                    normal = normal.negate();
                }

                return new LinecastPoint3D(pt, normal, linecastSubset.getLine());
            }

            return null;
        }

@Override
    public Vector3D getPoint1() {
        return p1;
    }

@Override
    public Vector3D getPoint2() {
        return p2;
    }

@Override
    public Vector3D getPoint3() {
        return p3;
    }

@Override
    public List<Vector3D> getVertices() {
        return Arrays.asList(p1, p2, p3);
    }

@Override
    public double getSize() {
        final Vector3D v1 = p1.vectorTo(p2);
        final Vector3D v2 = p1.vectorTo(p3);
        return 0.5 * v1.cross(v2).norm();
    }

@Override
    public Vector3D getCentroid() {
        return Vector3D.centroid(p1, p2, p3);
    }

@Override
    public SimpleTriangle3D reverse() {
        final Plane rPlane = getPlane().reverse();

        return new SimpleTriangle3D(rPlane, p1, p3, p2); // reverse point ordering
    }

@Override
    public SimpleTriangle3D transform(final Transform<Vector3D> transform) {
        final Plane tPlane = getPlane().transform(transform);
        final Vector3D t1 = transform.apply(p1);
        final Vector3D t2 = transform.apply(p2);
        final Vector3D t3 = transform.apply(p3);

        return new SimpleTriangle3D(tPlane, t1, t2, t3);
    }

public Vector3D getOrigin() {
        return normal.multiply(-originOffset);
    }

docstring:
/** Get the offset of the spatial origin ({@code 0, 0, 0}) with respect to the plane.
     * @return the offset of the origin with respect to the plane.
     */

method_definition:
public double getOriginOffset() {
        return originOffset;
    }

docstring:
/** Get the plane normal vector.
     * @return plane normal vector
     */

method_definition:
public Vector3D.Unit getNormal() {
        return normal;
    }

public EmbeddingPlane getEmbedding() {
        final Vector3D.Unit u = normal.orthogonal();
        final Vector3D.Unit v = normal.cross(u).normalize();

        return new EmbeddingPlane(u, v, normal, originOffset, getPrecision());
    }

@Override
    public double offset(final Vector3D point) {
        return point.dot(normal) + originOffset;
    }

public double offset(final Line3D line) {
        if (!isParallel(line)) {
            return 0.0;
        }
        return offset(line.getOrigin());
    }

public double offset(final Plane plane) {
        if (!isParallel(plane)) {
            return 0.0;
        }
        return originOffset + (similarOrientation(plane) ? -plane.originOffset : plane.originOffset);
    }

@Override
    public boolean contains(final Vector3D p) {
        return getPrecision().eqZero(offset(p));
    }

public boolean contains(final Line3D line) {
        return isParallel(line) && contains(line.getOrigin());
    }

public boolean contains(final Plane plane) {
        final double angle = normal.angle(plane.normal);
        final Precision.DoubleEquivalence precision = getPrecision();

        return ((precision.eqZero(angle)) && precision.eq(originOffset, plane.originOffset)) ||
                ((precision.eq(angle, Math.PI)) && precision.eq(originOffset, -plane.originOffset));
    }

@Override
    public Vector3D project(final Vector3D point) {
        return getOrigin().add(point.reject(normal));
    }

public Line3D project(final Line3D line) {
        final Vector3D direction = line.getDirection();
        final Vector3D projection = normal.multiply(direction.dot(normal) * (1 / normal.normSq()));

        final Vector3D projectedLineDirection = direction.subtract(projection);
        final Vector3D p1 = project(line.getOrigin());
        final Vector3D p2 = p1.add(projectedLineDirection);

        return Lines3D.fromPoints(p1, p2, getPrecision());
    }

@Override
    public PlaneConvexSubset span() {
        return Planes.subsetFromConvexArea(getEmbedding(), ConvexArea.full());
    }

public boolean isParallel(final Line3D line) {
        final double dot = normal.dot(line.getDirection());

        return getPrecision().eqZero(dot);
    }

public boolean isParallel(final Plane plane) {
        return getPrecision().eqZero(normal.cross(plane.normal).norm());
    }

@Override
    public boolean similarOrientation(final Hyperplane<Vector3D> other) {
        return (((Plane) other).normal).dot(normal) > 0;
    }

public Vector3D intersection(final Line3D line) {
        final Vector3D direction = line.getDirection();
        final double dot = normal.dot(direction);

        if (getPrecision().eqZero(dot)) {
            return null;
        }

        final Vector3D point = line.pointAt(0);
        final double k = -(originOffset + normal.dot(point)) / dot;

        return Vector3D.Sum.of(point)
                .addScaled(k, direction)
                .get();
    }

public Line3D intersection(final Plane other) {
        final Vector3D direction = normal.cross(other.normal);

        if (getPrecision().eqZero(direction.norm())) {
            return null;
        }

        final Vector3D point = intersection(this, other, Planes.fromNormal(direction, getPrecision()));

        return Lines3D.fromPointAndDirection(point, direction, getPrecision());
    }

docstring:
/** Build a new reversed version of this plane, with opposite orientation.
     * @return a new reversed plane
     */

method_definition:
@Override
    public Plane reverse() {
        return new Plane(normal.negate(), -originOffset, getPrecision());
    }

@Override
    public Plane transform(final Transform<Vector3D> transform) {
        // create 3 representation points lying on the plane, transform them,
        // and use the transformed points to create a new plane

        final Vector3D u = normal.orthogonal();
        final Vector3D v = normal.cross(u);

        final Vector3D p1 = getOrigin();
        final Vector3D p2 = p1.add(u);
        final Vector3D p3 = p1.add(v);

        final Vector3D t1 = transform.apply(p1);
        final Vector3D t2 = transform.apply(p2);
        final Vector3D t3 = transform.apply(p3);

        return Planes.fromPoints(t1, t2, t3, getPrecision());
    }

public Plane translate(final Vector3D translation) {
        final Vector3D tOrigin = getOrigin().add(translation);

        return Planes.fromPointAndNormal(tOrigin, normal, getPrecision());
    }

public Plane rotate(final Vector3D center, final QuaternionRotation rotation) {
        final Vector3D delta = getOrigin().subtract(center);
        final Vector3D tOrigin = center.add(rotation.apply(delta));

        // we can directly apply the rotation to the normal since it will transform
        // it properly (there is no translation or scaling involved)
        final Vector3D.Unit tNormal = rotation.apply(normal).normalize();

        return Planes.fromPointAndNormal(tOrigin, tNormal, getPrecision());
    }

public boolean eq(final Plane other, final Precision.DoubleEquivalence precision) {
        return getOrigin().eq(other.getOrigin(), precision) &&
                normal.eq(other.normal, precision);
    }

@Override
    public int hashCode() {
        return Objects.hash(normal, originOffset, getPrecision());
    }

@Override
    public boolean equals(final Object obj) {
        if (this == obj) {
            return true;
        } else if (obj == null || obj.getClass() != this.getClass()) {
            return false;
        }

        final Plane other = (Plane) obj;

        return Objects.equals(this.normal, other.normal) &&
                Double.compare(this.originOffset, other.originOffset) == 0 &&
                Objects.equals(this.getPrecision(), other.getPrecision());
    }

@Override
    public String toString() {
        final StringBuilder sb = new StringBuilder();
        sb.append(getClass().getSimpleName())
            .append("[origin= ")
            .append(getOrigin())
            .append(", normal= ")
            .append(normal)
            .append(']');

        return sb.toString();
    }

public static Vector3D intersection(final Plane plane1, final Plane plane2, final Plane plane3) {

        // coefficients of the three planes linear equations
        final double a1 = plane1.normal.getX();
        final double b1 = plane1.normal.getY();
        final double c1 = plane1.normal.getZ();
        final double d1 = plane1.originOffset;

        final double a2 = plane2.normal.getX();
        final double b2 = plane2.normal.getY();
        final double c2 = plane2.normal.getZ();
        final double d2 = plane2.originOffset;

        final double a3 = plane3.normal.getX();
        final double b3 = plane3.normal.getY();
        final double c3 = plane3.normal.getZ();
        final double d3 = plane3.originOffset;

        // direct Cramer resolution of the linear system
        // (this is still feasible for a 3x3 system)
        final double a23 = (b2 * c3) - (b3 * c2);
        final double b23 = (c2 * a3) - (c3 * a2);
        final double c23 = (a2 * b3) - (a3 * b2);
        final double determinant = (a1 * a23) + (b1 * b23) + (c1 * c23);

        // use the precision context of the first plane to determine equality
        if (plane1.getPrecision().eqZero(determinant)) {
            return null;
        }

        final double r = 1.0 / determinant;
        return Vector3D.of((-a23 * d1 - (c1 * b3 - c3 * b1) * d2 - (c2 * b1 - c1 * b2) * d3) * r,
                (-b23 * d1 - (c3 * a1 - c1 * a3) * d2 - (c1 * a2 - c2 * a1) * d3) * r,
                (-c23 * d1 - (b1 * a3 - b3 * a1) * d2 - (b2 * a1 - b1 * a2) * d3) * r);
    }

