public static AffineTransformMatrix3D createScale(final double x, final double y, final double z) {
        return new AffineTransformMatrix3D(
                    x, 0, 0, 0,
                    0, y, 0, 0,
                    0, 0, z, 0
                );
    }

public static AffineTransformMatrix3D createRotation(final Vector3D center, final QuaternionRotation rotation) {
        return createTranslation(center.negate())
                .rotate(rotation)
                .translate(center);
    }

docstring:
/** Multiply two transform matrices together and return the result as a new transform instance.
     * @param a first transform
     * @param b second transform
     * @return the transform computed as {@code a x b}
     */

method_definition:
private static AffineTransformMatrix3D multiply(final AffineTransformMatrix3D a,
            final AffineTransformMatrix3D b) {

        // calculate the matrix elements
        final double c00 = Vectors.linearCombination(a.m00, b.m00, a.m01, b.m10, a.m02, b.m20);
        final double c01 = Vectors.linearCombination(a.m00, b.m01, a.m01, b.m11, a.m02, b.m21);
        final double c02 = Vectors.linearCombination(a.m00, b.m02, a.m01, b.m12, a.m02, b.m22);
        final double c03 = Vectors.linearCombination(a.m00, b.m03, a.m01, b.m13, a.m02, b.m23) + a.m03;

        final double c10 = Vectors.linearCombination(a.m10, b.m00, a.m11, b.m10, a.m12, b.m20);
        final double c11 = Vectors.linearCombination(a.m10, b.m01, a.m11, b.m11, a.m12, b.m21);
        final double c12 = Vectors.linearCombination(a.m10, b.m02, a.m11, b.m12, a.m12, b.m22);
        final double c13 = Vectors.linearCombination(a.m10, b.m03, a.m11, b.m13, a.m12, b.m23) + a.m13;

        final double c20 = Vectors.linearCombination(a.m20, b.m00, a.m21, b.m10, a.m22, b.m20);
        final double c21 = Vectors.linearCombination(a.m20, b.m01, a.m21, b.m11, a.m22, b.m21);
        final double c22 = Vectors.linearCombination(a.m20, b.m02, a.m21, b.m12, a.m22, b.m22);
        final double c23 = Vectors.linearCombination(a.m20, b.m03, a.m21, b.m13, a.m22, b.m23) + a.m23;

        return new AffineTransformMatrix3D(
                    c00, c01, c02, c03,
                    c10, c11, c12, c13,
                    c20, c21, c22, c23
                );
    }

@Override
    public PlaneSubset.Embedded getEmbedded() {
        return this;
    }

@Override
    public RegionBSPTree2D getSubspaceRegion() {
        return region;
    }

@Override
    public List<PlaneConvexSubset> toConvex() {
        final List<ConvexArea> areas = region.toConvex();

        final List<PlaneConvexSubset> facets = new ArrayList<>(areas.size());

        for (final ConvexArea area : areas) {
            facets.add(Planes.subsetFromConvexArea(getPlane(), area));
        }

        return facets;
    }

@Override
    public List<Triangle3D> toTriangles() {
        final EmbeddingPlane plane = getPlane();
        final List<Triangle3D> triangles = new ArrayList<>();

        List<Vector3D> vertices;
        for (final ConvexArea area : region.toConvex()) {
            if (area.isInfinite()) {
                throw new IllegalStateException("Cannot convert infinite plane subset to triangles: " + this);
            }

            vertices = plane.toSpace(area.getVertices());

            triangles.addAll(Planes.convexPolygonToTriangleFan(plane, vertices));
        }

        return triangles;
    }

@Override
    public Bounds3D getBounds() {
        return getBoundsFromSubspace(region);
    }

docstring:
/** {@inheritDoc}
     *
     * <p>In all cases, the current instance is not modified. However, In order to avoid
     * unnecessary copying, this method will use the current instance as the split value when
     * the instance lies entirely on the plus or minus side of the splitter. For example, if
     * this instance lies entirely on the minus side of the splitter, the plane subset
     * returned by {@link Split#getMinus()} will be this instance. Similarly, {@link Split#getPlus()}
     * will return the current instance if it lies entirely on the plus side. Callers need to make
     * special note of this, since this class is mutable.</p>
     */

method_definition:
@Override
    public Split<EmbeddedTreePlaneSubset> split(final Hyperplane<Vector3D> splitter) {
        return Planes.subspaceSplit((Plane) splitter, this,
            (p, r) -> new EmbeddedTreePlaneSubset(p, (RegionBSPTree2D) r));
    }

@Override
    public EmbeddedTreePlaneSubset transform(final Transform<Vector3D> transform) {
        final EmbeddingPlane.SubspaceTransform subTransform =
                getPlane().getEmbedding().subspaceTransform(transform);

        final RegionBSPTree2D tRegion = RegionBSPTree2D.empty();
        tRegion.copy(region);
        tRegion.transform(subTransform.getTransform());

        return new EmbeddedTreePlaneSubset(subTransform.getPlane(), tRegion);
    }

public void add(final PlaneConvexSubset subset) {
        Planes.validatePlanesEquivalent(getPlane(), subset.getPlane());

        final PlaneConvexSubset.Embedded embedded = subset.getEmbedded();
        final Rotation2D rot = getEmbeddedRegionRotation(embedded);

        final ConvexArea subspaceArea = embedded.getSubspaceRegion();

        final ConvexArea toAdd = rot != null ?
                subspaceArea.transform(rot) :
                subspaceArea;

        region.add(toAdd);
    }

public void add(final EmbeddedTreePlaneSubset subset) {
        Planes.validatePlanesEquivalent(getPlane(), subset.getPlane());

        final RegionBSPTree2D otherTree = subset.getSubspaceRegion();
        final Rotation2D rot = getEmbeddedRegionRotation(subset);

        final RegionBSPTree2D regionToAdd;
        if (rot != null) {
            // we need to transform the subspace region before adding
            regionToAdd = otherTree.copy();
            regionToAdd.transform(rot);
        } else {
            regionToAdd = otherTree;
        }

        region.union(regionToAdd);
    }

private Rotation2D getEmbeddedRegionRotation(final PlaneSubset.Embedded embedded) {
        // check if we need to apply a rotation to the given embedded subspace
        final EmbeddingPlane thisPlane = getPlane();
        final EmbeddingPlane otherPlane = embedded.getPlane();

        final Precision.DoubleEquivalence precision = thisPlane.getPrecision();

        final double uDot = thisPlane.getU().dot(otherPlane.getU());
        if (!precision.eq(uDot, 1.0)) {
            final Vector2D otherPlaneU = thisPlane.toSubspace(otherPlane.getOrigin().add(otherPlane.getU()));
            final double angle = Math.atan2(otherPlaneU.getY(), otherPlaneU.getX());

            return Rotation2D.of(angle);
        }

        return null;
    }

@Override
    public Stream<PlaneConvexSubset> boundaryStream() {
        return getBoundaries().stream();
    }

@Override
    public double getSize() {
        if (isFull()) {
            return Double.POSITIVE_INFINITY;
        }

        double volumeSum = 0.0;

        for (final PlaneConvexSubset boundary : getBoundaries()) {
            if (boundary.isInfinite()) {
                return Double.POSITIVE_INFINITY;
            }

            final Plane boundaryPlane = boundary.getPlane();
            final double boundaryArea = boundary.getSize();
            final Vector3D boundaryCentroid = boundary.getCentroid();

            volumeSum += boundaryArea * boundaryCentroid.dot(boundaryPlane.getNormal());
        }

        return volumeSum / 3.0;
    }

@Override
    public Vector3D getCentroid() {
        double volumeSum = 0.0;

        double sumX = 0.0;
        double sumY = 0.0;
        double sumZ = 0.0;

        for (final PlaneConvexSubset boundary : getBoundaries()) {
            if (boundary.isInfinite()) {
                return null;
            }

            final Plane boundaryPlane = boundary.getPlane();
            final double boundaryArea = boundary.getSize();
            final Vector3D boundaryCentroid = boundary.getCentroid();

            final double scaledVolume = boundaryArea * boundaryCentroid.dot(boundaryPlane.getNormal());

            volumeSum += scaledVolume;

            sumX += scaledVolume * boundaryCentroid.getX();
            sumY += scaledVolume * boundaryCentroid.getY();
            sumZ += scaledVolume * boundaryCentroid.getZ();
        }

        if (volumeSum > 0) {
            final double size = volumeSum / 3.0;

            // Since the volume we used when adding together the boundary contributions
            // was 3x the actual pyramid size, we'll multiply by 1/4 here instead
            // of 3/4 to adjust for the actual centroid position in each pyramid.
            final double centroidScale = 1.0 / (4 * size);
            return Vector3D.of(
                    sumX * centroidScale,
                    sumY * centroidScale,
                    sumZ * centroidScale);
        }

        return null;
    }

@Override
    public Split<ConvexVolume> split(final Hyperplane<Vector3D> splitter) {
        return splitInternal(splitter, this, PlaneConvexSubset.class, ConvexVolume::new);
    }

@Override
    public RegionBSPTree3D toTree() {
        return RegionBSPTree3D.from(getBoundaries(), true);
    }

@Override
    public PlaneConvexSubset trim(final HyperplaneConvexSubset<Vector3D> convexSubset) {
        return (PlaneConvexSubset) super.trim(convexSubset);
    }

public ConvexVolume transform(final Transform<Vector3D> transform) {
        return transformInternal(transform, this, PlaneConvexSubset.class, ConvexVolume::new);
    }

