/** Create a new instance with an initial value set to the {@link Vector3D#ZERO zero vector}.
         * @return new instance set to zero
         */

method_definition:
public static Sum create() {
            return new Sum(Vector3D.ZERO);
        }

public static Sum of(final Vector3D initial) {
            return new Sum(initial);
        }

public static Sum of(final Vector3D first, final Vector3D... more) {
            final Sum s = new Sum(first);
            for (final Vector3D v : more) {
                s.add(v);
            }
            return s;
        }

public Bounds3D getBounds(final BoundarySource3D src) {
        final Bounds3D.Builder builder = Bounds3D.builder();

        try (Stream<PlaneConvexSubset> stream = src.boundaryStream()) {
            final Iterator<PlaneConvexSubset> it = stream.iterator();

            PlaneConvexSubset boundary;
            while (it.hasNext()) {
                boundary = it.next();

                if (!boundary.isFinite()) {
                    return null;
                }

                builder.addAll(boundary.getVertices());
            }
        }

        return builder.hasBounds() ?
                builder.build() :
                null;
    }

