docstring:
/** Build the BSP tree circle approximation.
         * @return the BSP tree circle approximation
         */

method_definition:
public RegionBSPTree2D build() {
            final RegionBSPTree2D tree = RegionBSPTree2D.empty();
            final RegionBSPTree2D.RegionNode2D root = tree.getRoot();

            if (segments < SPLIT_THRESHOLD) {
                insert(root, 0, segments);
            } else {
                // split the circle in half (or mostly in half if an odd number of segments)
                final int splitIdx = segments / 2;
                final Vector2D p0 = pointAt(0);
                final Vector2D p1 = pointAt(splitIdx);

                root.cut(Lines.fromPoints(p0, p1, circle.getPrecision()), RegionCutRule.INHERIT);

                splitAndInsert(root.getPlus(), 0, splitIdx);
                splitAndInsert(root.getMinus(), splitIdx, segments);
            }

            return tree;
        }

private void splitAndInsert(final RegionBSPTree2D.RegionNode2D node, final int startIdx, final int stopIdx) {
            if (stopIdx - startIdx >= SPLIT_THRESHOLD) {
                final int splitIdx = ((stopIdx - startIdx + 1) / 2) + startIdx;
                final Vector2D p0 = circle.getCenter();
                final Vector2D p1 = pointAt(splitIdx);

                node.cut(Lines.fromPoints(p0, p1, circle.getPrecision()), RegionCutRule.INHERIT);

                splitAndInsert(node.getPlus(), startIdx, splitIdx);
                splitAndInsert(node.getMinus(), splitIdx, stopIdx);
            } else {
                insert(node, startIdx, stopIdx);
            }
        }

private void insert(final RegionBSPTree2D.RegionNode2D node, final int startIdx, final int stopIdx) {

            RegionBSPTree2D.RegionNode2D currNode = node;
            Vector2D currPt;
            Vector2D prevPt = pointAt(startIdx);
            for (int i = startIdx + 1; i <= stopIdx; ++i) {
                currPt = pointAt(i);

                currNode = currNode.cut(Lines.fromPoints(prevPt, currPt, circle.getPrecision()))
                        .getMinus();

                prevPt = currPt;
            }
        }

private Vector2D pointAt(final int idx) {
            return PolarCoordinates.toCartesian(circle.getRadius(), idx * angleDelta)
                    .add(circle.getCenter());
        }

public static Parallelogram unitSquare(final Precision.DoubleEquivalence precision) {
        return fromTransformedUnitSquare(AffineTransformMatrix2D.identity(), precision);
    }

public static Parallelogram axisAligned(final Vector2D a, final Vector2D b,
            final Precision.DoubleEquivalence precision) {

        final double minX = Math.min(a.getX(), b.getX());
        final double maxX = Math.max(a.getX(), b.getX());

        final double minY = Math.min(a.getY(), b.getY());
        final double maxY = Math.max(a.getY(), b.getY());

        final double xDelta = maxX - minX;
        final double yDelta = maxY - minY;

        final Vector2D scale = Vector2D.of(xDelta, yDelta);
        final Vector2D position = Vector2D.of(
                    (0.5 * xDelta) + minX,
                    (0.5 * yDelta) + minY
                );

        return builder(precision)
                .setScale(scale)
                .setPosition(position)
                .build();
    }

public static Parallelogram fromTransformedUnitSquare(final Transform<Vector2D> transform,
            final Precision.DoubleEquivalence precision) {

        final List<Vector2D> vertices = UNIT_SQUARE_VERTICES.stream()
                .map(transform).collect(Collectors.toList());

        final int len = vertices.size();
        final boolean preservesOrientation = transform.preservesOrientation();

        final List<LineConvexSubset> boundaries = new ArrayList<>(UNIT_SQUARE_VERTICES.size());

        Vector2D p0;
        Vector2D p1;
        LineConvexSubset boundary;
        for (int i = 0; i < len; ++i) {
            p0 = vertices.get(i);
            p1 = vertices.get((i + 1) % len);

            if (precision.eqZero(p0.distance(p1))) {
                throw new IllegalArgumentException(MessageFormat.format(
                        "Parallelogram has zero size: vertices {0} and {1} are equivalent", p0, p1));
            }

            boundary = preservesOrientation ?
                    Lines.segmentFromPoints(p0, p1, precision) :
                    Lines.segmentFromPoints(p1, p0, precision);

            boundaries.add(boundary);
        }

        return new Parallelogram(boundaries);
    }

public static Builder builder(final Precision.DoubleEquivalence precision) {
        return new Builder(precision);
    }

public Builder setPosition(final Vector2D pos) {
            this.position = pos;
            return this;
        }

public Builder setScale(final Vector2D scaleFactors) {
            this.scale = scaleFactors;
            return this;
        }

public Builder setScale(final double x, final double y) {
            return setScale(Vector2D.of(x, y));
        }

public Builder setScale(final double scaleFactor) {
            return setScale(scaleFactor, scaleFactor);
        }

public Builder setRotation(final Rotation2D rot) {
            this.rotation = rot;
            return this;
        }

public Builder setXDirection(final Vector2D xDirection) {
            return setRotation(
                    Rotation2D.createVectorRotation(Vector2D.Unit.PLUS_X, xDirection));
        }

public Builder setYDirection(final Vector2D yDirection) {
            return setRotation(
                    Rotation2D.createVectorRotation(Vector2D.Unit.PLUS_Y, yDirection));
        }

public Parallelogram build() {
            final AffineTransformMatrix2D transform = AffineTransformMatrix2D.createScale(scale)
                    .rotate(rotation)
                    .translate(position);

            return fromTransformedUnitSquare(transform, precision);
        }

public void add(final LineConvexSubset subset) {
        addPathElement(new ConnectableLineSubset(subset));
    }

public void add(final Iterable<? extends LineConvexSubset> subsets) {
        for (final LineConvexSubset subset : subsets) {
            add(subset);
        }
    }

public void connect(final Iterable<? extends LineConvexSubset> subsets) {
        final List<ConnectableLineSubset> newEntries = new ArrayList<>();

        for (final LineConvexSubset subset : subsets) {
            newEntries.add(new ConnectableLineSubset(subset));
        }

        connectPathElements(newEntries);
    }

public List<LinePath> connectAll(final Iterable<LineConvexSubset> subsets) {
        add(subsets);
        return connectAll();
    }

public List<LinePath> connectAll() {
        final List<ConnectableLineSubset> roots = computePathRoots();
        final List<LinePath> paths = new ArrayList<>(roots.size());

        for (final ConnectableLineSubset root : roots) {
            paths.add(toPath(root));
        }

        return paths;
    }

private LinePath toPath(final ConnectableLineSubset root) {
        final LinePath.Builder builder = LinePath.builder(null);

        builder.append(root.getLineSubset());

        ConnectableLineSubset current = root.getNext();

        while (current != null && current != root) {
            builder.append(current.getLineSubset());
            current = current.getNext();
        }

        return builder.build();
    }

