/** Set the minimum horizontal offset for tree nodes from their parents.
     * @param treeParentXOffsetMin minimum offset
     */

method_definition:
public void setTreeParentXOffsetMin(final double treeParentXOffsetMin) {
        this.treeParentXOffsetMin = treeParentXOffsetMin;
    }

public void write(final RegionBSPTree2D tree, final File file) {
        final Deque<RegionNode2D> nodeQueue = new LinkedList<>();
        nodeQueue.add(tree.getRoot());

        final Map<RegionNode2D, String> nodeNames = new HashMap<>();

        final String names = DEFAULT_NODE_NAMES;
        RegionNode2D node;
        for (int i = 0; i < names.length() && !nodeQueue.isEmpty(); ++i) {
            node = nodeQueue.removeFirst();

            nodeNames.put(node, names.substring(i, i + 1));

            if (node.isInternal()) {
                nodeQueue.add(node.getMinus());
                nodeQueue.add(node.getPlus());
            }
        }

        write(tree, nodeNames, file);
    }

public void write(final RegionBSPTree2D tree, final Map<RegionNode2D, String> nodeNames, final File file) {
        try {
            final DocumentBuilderFactory docBuilderFactory = DocumentBuilderFactory.newInstance();
            final DocumentBuilder docBuilder = docBuilderFactory.newDocumentBuilder();

            final Document doc = docBuilder.newDocument();

            // create the svg element
            final Element root = svgElement("svg", doc);
            doc.appendChild(root);

            root.setAttribute("version", SVG_VERSION);
            root.setAttribute(WIDTH_ATTR, String.valueOf(WIDTH));
            root.setAttribute(HEIGHT_ATTR, String.valueOf(HEIGHT));

            // add a defs element for later use
            final Element defs = svgElement("defs", doc);
            root.appendChild(defs);

            // add a style element
            final Element style = svgElement("style", doc);
            root.appendChild(style);
            style.setTextContent(STYLE);

            // write the tree
            writeTreeGeometryArea(tree, nodeNames, root, defs, doc);
            writeTreeStructureArea(tree, nodeNames, root, doc);

            // output to the target file
            final TransformerFactory transformerFactory = TransformerFactory.newInstance();
            final Transformer transformer = transformerFactory.newTransformer();
            transformer.setOutputProperty(OutputKeys.INDENT, "yes");
            transformer.setOutputProperty(INDENT_AMOUNT_KEY, String.valueOf(INDENT_AMOUNT));

            final DOMSource source = new DOMSource(doc);
            final StreamResult target = new StreamResult(file);

            transformer.transform(source, target);

        } catch (final ParserConfigurationException | TransformerException e) {
            // throw as a runtime exception for convenience
            throw new RuntimeException("Failed to create SVG", e);
        }
    }

private void writeTreeGeometryArea(final RegionBSPTree2D tree, final Map<RegionNode2D, String> nodeNames,
            final Element root, final Element defs, final Document doc) {
        final double geometrySvgX = MARGIN;
        final double geometrySvgY = MARGIN;
        final double geometrySvgWidth = (GEOMETRY_AREA_WIDTH_FACTOR * WIDTH) - (2 * MARGIN);
        final double geometrySvgHeight = HEIGHT - (2 * MARGIN);

        defineClipRect(GEOMETRY_AREA_CLIP_PATH_ID,
                geometrySvgX, geometrySvgY,
                geometrySvgWidth, geometrySvgHeight,
                defs, doc);

        // create the box containing the 2D content
        final Element geometryGroup = svgElement("g", doc);
        root.appendChild(geometryGroup);
        geometryGroup.setAttribute(CLASS_ATTR, "geometry");
        geometryGroup.setAttribute("clip-path", "url(#" + GEOMETRY_AREA_CLIP_PATH_ID + ")");

        // set up the transform so we can write geometry elements with their natural coordinates
        final AffineTransformMatrix2D transform = computeGeometryTransform(bounds, geometrySvgX, geometrySvgY,
                geometrySvgWidth, geometrySvgHeight);

        // add the tree geometry
        tree.accept(new TreeGeometryVisitor(transform, nodeNames, geometryGroup, doc));

        // create a box outlining the geometry area
        final Element border = svgElement(RECT_ELEMENT, doc);
        border.setAttribute(CLASS_ATTR, "geometry-border");
        floatAttr(border, X_ATTR, geometrySvgX);
        floatAttr(border, Y_ATTR, geometrySvgY);
        floatAttr(border, WIDTH_ATTR, geometrySvgWidth);
        floatAttr(border, HEIGHT_ATTR, geometrySvgHeight);

        root.appendChild(border);

    }

private void writeTreeStructureArea(final RegionBSPTree2D tree, final Map<RegionNode2D, String> nodeNames,
            final Element root, final Document doc) {
        final Element treeGroup = svgElement("g", doc);
        root.appendChild(treeGroup);
        treeGroup.setAttribute(CLASS_ATTR, "tree");

        final double offsetX = ((1 - TREE_AREA_WIDTH_FACTOR) * WIDTH) + MARGIN;
        final double offsetY = MARGIN;

        final double svgWidth = (TREE_AREA_WIDTH_FACTOR * WIDTH) - (2 * MARGIN);
        final double svgHeight = HEIGHT - (2 * MARGIN);

        treeGroup.setAttribute("transform", "translate(" + offsetX + " " + offsetY + ")");

        tree.accept(new TreeStructureVisitor(tree.height(), svgWidth, svgHeight, nodeNames, treeGroup, doc));
    }

private static AffineTransformMatrix2D computeGeometryTransform(final Bounds2D bounds,
            final double svgX, final double svgY, final double svgWidth, final double svgHeight) {

        final Vector2D boundsDiagonal = bounds.getDiagonal();

        return AffineTransformMatrix2D
            .createTranslation(bounds.getMin().negate())
            .scale(svgWidth / boundsDiagonal.getX(), -svgHeight / boundsDiagonal.getY())
            .translate(svgX, svgY + svgHeight);
    }

private void defineClipRect(final String id, final double x, final double y,
            final double svgWidth, final double svgHeight, final Element defs, final Document doc) {

        final Element clipPath = svgElement("clipPath", doc);
        clipPath.setAttribute("id", id);

        defs.appendChild(clipPath);

        final Element rect = svgElement(RECT_ELEMENT, doc);
        floatAttr(rect, X_ATTR, x);
        floatAttr(rect, Y_ATTR, y);
        floatAttr(rect, WIDTH_ATTR, svgWidth);
        floatAttr(rect, HEIGHT_ATTR, svgHeight);

        clipPath.appendChild(rect);
    }

private static void floatAttr(final Element element, final String name, final double value) {
        element.setAttribute(name, String.valueOf(value));
    }

private static Element svgElement(final String name, final Document doc) {
        return doc.createElementNS(SVG_NAMESPACE, name);
    }

@Override
        public Order visitOrder(final RegionNode2D internalNode) {
            return Order.NODE_MINUS_PLUS;
        }

@Override
        public Result visit(final RegionNode2D node) {
            ++count;

            final String name = (nodeNames != null && nodeNames.containsKey(node)) ?
                    nodeNames.get(node) :
                    String.valueOf(count);

            visitNode(name, node);

            return Result.CONTINUE;
        }

protected Element createChild(final String name) {
            final Element child = createElement(name);
            parent.appendChild(child);

            return child;
        }

protected Element createElement(final String name) {
            return svgElement(name, doc);
        }

protected Element createNodeNameElement(final String name, final Vector2D svgPt) {
            final Element text = createElement("text");
            text.setAttribute(CLASS_ATTR, "node-name");
            text.setAttribute("dominant-baseline", "middle");
            floatAttr(text, X_ATTR, svgPt.getX());
            floatAttr(text, Y_ATTR, svgPt.getY());
            text.setTextContent(name);

            return text;
        }

protected Element createPathElement(final String className, final Vector2D svgStart, final Vector2D svgEnd) {
            final Element path = createElement(PATH_ELEMENT);
            path.setAttribute(CLASS_ATTR, className);

            final StringBuilder pathStr = new StringBuilder();
            pathStr.append(PATH_MOVE_TO)
                .append(pointString(svgStart))
                .append(SPACE)
                .append(PATH_LINE_TO)
                .append(pointString(svgEnd));

            path.setAttribute("d", pathStr.toString());

            return path;
        }

protected String pointString(final Vector2D pt) {
            return pt.getX() + " " + pt.getY();
        }

@Override
        protected void visitNode(final String name, final RegionNode2D node) {
            if (node.isLeaf()) {
                visitLeafNode(name, node);
            } else {
                visitInternalNode(name, node);
            }
        }

private void visitLeafNode(final String name, final RegionNode2D node) {
            final RegionBSPTree2D tree = node.getNodeRegion().toTree();
            tree.intersection(boundsRegion.toTree());

            final Vector2D svgCentroid = toSvgSpace(tree.getCentroid());

            labelGroup.appendChild(createNodeNameElement(name, svgCentroid));

            if (node.isInside()) {
                for (final LinePath linePath : tree.getBoundaryPaths()) {
                    final Element path = createElement(PATH_ELEMENT);
                    pathGroup.appendChild(path);
                    path.setAttribute(CLASS_ATTR, "inside");

                    final StringBuilder sb = new StringBuilder();

                    for (final Vector2D pt : linePath.getVertexSequence()) {
                        if (sb.length() < 1) {
                            sb.append(PATH_MOVE_TO);
                        } else {
                            sb.append(SPACE)
                                .append(PATH_LINE_TO);
                        }

                        sb.append(pointString(toSvgSpace(pt)));
                    }

                    path.setAttribute("d", sb.toString());
                }
            }
        }

private void visitInternalNode(final String name, final RegionNode2D node) {
            final LineConvexSubset trimmedCut = boundsRegion.trim(node.getCut());

            final Vector2D svgStart = toSvgSpace(trimmedCut.getStartPoint());
            final Vector2D svgEnd = toSvgSpace(trimmedCut.getEndPoint());

            final Vector2D svgMid = svgStart.lerp(svgEnd, 0.5);

            labelGroup.appendChild(createNodeNameElement(name, svgMid));

            pathGroup.appendChild(createPathElement("cut", svgStart, svgEnd));

            final String arrowPathString = createCutArrowPathString(svgStart, svgEnd);
            if (arrowPathString != null) {
                final Element arrowPath = createElement(PATH_ELEMENT);
                pathGroup.appendChild(arrowPath);
                arrowPath.setAttribute(CLASS_ATTR, "arrow");
                arrowPath.setAttribute("d", arrowPathString);
            }

            final RegionCutBoundary<Vector2D> boundary = node.getCutBoundary();
            if (boundary != null) {
                addRegionBoundaries(boundary.getInsideFacing());
                addRegionBoundaries(boundary.getOutsideFacing());
            }
        }

docstring:
/** Add path elements for the given list of region boundaries.
         * @param boundaries boundaries to add path elements for
         */

method_definition:
private void addRegionBoundaries(final List<HyperplaneConvexSubset<Vector2D>> boundaries) {
            LineConvexSubset trimmed;
            for (final HyperplaneConvexSubset<Vector2D> boundary : boundaries) {
                trimmed = boundsRegion.trim(boundary);

                if (trimmed != null) {
                    pathGroup.appendChild(createPathElement(
                            "region-boundary",
                            toSvgSpace(trimmed.getStartPoint()),
                            toSvgSpace(trimmed.getEndPoint())));
                }
            }
        }

private String createCutArrowPathString(final Vector2D svgStart, final Vector2D svgEnd) {
            final Vector2D dir = svgStart.vectorTo(svgEnd);
            if (!dir.eq(Vector2D.ZERO, PRECISION)) {

                final double az = Math.atan2(dir.getY(), dir.getX());
                final Vector2D upperArrowPt = PolarCoordinates
                        .toCartesian(ARROW_LENGTH, az + ARROW_ANGLE)
                        .add(svgEnd);

                final Vector2D lowerArrowPt = PolarCoordinates
                        .toCartesian(ARROW_LENGTH, az - ARROW_ANGLE)
                        .add(svgEnd);

                final StringBuilder sb = new StringBuilder();
                sb.append(PATH_MOVE_TO)
                    .append(pointString(upperArrowPt))
                    .append(SPACE)
                    .append(PATH_LINE_TO)
                    .append(pointString(svgEnd))
                    .append(SPACE)
                    .append(PATH_LINE_TO)
                    .append(pointString(lowerArrowPt));

                return sb.toString();
            }

            return null;
        }

private Vector2D toSvgSpace(final Vector2D pt) {
            return transform.apply(pt);
        }

@Override
        protected void visitNode(final String name, final RegionNode2D node) {
            final Vector2D loc = getNodeLocation(node);
            nodeLocations.put(node, loc);

            final Element nodeGroup = createChild("g");
            nodeGroup.setAttribute(CLASS_ATTR, getNodeClassNames(name, node));

            nodeGroup.appendChild(createNodeNameElement(name, loc));

            final Vector2D parentLoc = nodeLocations.get(node.getParent());
            if (parentLoc != null) {
                final Vector2D offset = loc.vectorTo(parentLoc).withNorm(TREE_LINE_MARGIN);
                nodeGroup.appendChild(createPathElement("tree-path", loc.add(offset), parentLoc.subtract(offset)));
            }
        }

private String getNodeClassNames(final String name, final RegionNode2D node) {
            final StringBuilder sb = new StringBuilder();
            sb.append("node-").append(name);

            if (node.isLeaf()) {
                sb.append(SPACE)
                    .append(node.isInside() ? "inside-node" : "outside-node");
            }

            return sb.toString();
        }

private Vector2D getNodeLocation(final RegionNode2D node) {
            // find the node parent
            final RegionNode2D parent = node.getParent();
            final Vector2D parentLoc = nodeLocations.get(parent);
            if (parentLoc == null) {
                // this is the root node
                return Vector2D.of(
                        0.5 * svgWidth,
                        svgTop);
            } else {
                // align with the parent
                double parentXOffset = Math.max(
                        treeParentOffsetFactor * (svgWidth / (1 << parent.depth())),
                        treeParentXOffsetMin);
                if (node.isMinus()) {
                    parentXOffset = -parentXOffset;
                }

                return Vector2D.of(
                            parentLoc.getX() + parentXOffset,
                            parentLoc.getY() + TREE_VERTICAL_SPACING
                        );
            }
        }

public static void main(final String[] args) {
        final File outputFolder = new File(args.length > 0 ? args[0] : ".");
        final BSPTreeSVGWriter svgWriter = new BSPTreeSVGWriter(Bounds2D.from(Vector2D.of(-8, -8), Vector2D.of(8, 8)));
        svgWriter.setTreeParentOffsetFactor(0);
        svgWriter.setTreeParentXOffsetMin(20);

        final Precision.DoubleEquivalence precision = Precision.doubleEquivalenceOfEpsilon(1e-6);

        final RegionBSPTree2D tree = RegionBSPTree2D.empty();

        final LinePath path = LinePath.fromVertexLoop(Arrays.asList(
                    Vector2D.of(-4, 0),
                    Vector2D.of(-2, -3),
                    Vector2D.of(2, -3),
                    Vector2D.of(4, 0),
                    Vector2D.of(2, 3),
                    Vector2D.of(-2, 3)
                ), precision);
        tree.insert(path);

        svgWriter.write(tree, new File(outputFolder, "hex-unbalanced.svg"));
    }

public static void main(final String[] args) {
        final File outputFolder = new File(args.length > 0 ? args[0] : ".");
        final BSPTreeSVGWriter svgWriter = new BSPTreeSVGWriter(Bounds2D.from(Vector2D.of(-8, -8), Vector2D.of(8, 8)));

        final Precision.DoubleEquivalence precision = Precision.doubleEquivalenceOfEpsilon(1e-6);

        final RegionBSPTree2D result = LinePath.fromVertexLoop(Arrays.asList(
                    Vector2D.of(2, 0),
                    Vector2D.of(-4, 3),
                    Vector2D.of(-4, -3)
                ), precision).toTree();

        final RegionBSPTree2D other = LinePath.fromVertexLoop(Arrays.asList(
                Vector2D.of(-2, 0),
                Vector2D.of(4, -3),
                Vector2D.of(4, 3)
            ), precision).toTree();

        result.xor(other);

        svgWriter.write(result, new File(outputFolder, "xor.svg"));
    }

public static void main(final String[] args) {
        final File outputFolder = new File(args.length > 0 ? args[0] : ".");
        final BSPTreeSVGWriter svgWriter = new BSPTreeSVGWriter(Bounds2D.from(Vector2D.of(-8, -8), Vector2D.of(8, 8)));

        final Precision.DoubleEquivalence precision = Precision.doubleEquivalenceOfEpsilon(1e-6);

        final RegionBSPTree2D a = LinePath.fromVertexLoop(Arrays.asList(
                    Vector2D.of(2, 0),
                    Vector2D.of(-4, 3),
                    Vector2D.of(-4, -3)
                ), precision).toTree();

        final RegionBSPTree2D b = LinePath.fromVertexLoop(Arrays.asList(
                Vector2D.of(-2, 0),
                Vector2D.of(4, -3),
                Vector2D.of(4, 3)
            ), precision).toTree();

        final RegionBSPTree2D result = RegionBSPTree2D.empty();

        result.union(a, b);

        svgWriter.write(result, new File(outputFolder, "union.svg"));
    }

public static void main(final String[] args) {
        final File outputFolder = new File(args.length > 0 ? args[0] : ".");
        final BSPTreeSVGWriter svgWriter = new BSPTreeSVGWriter(Bounds2D.from(Vector2D.of(-8, -8), Vector2D.of(8, 8)));

        final Precision.DoubleEquivalence precision = Precision.doubleEquivalenceOfEpsilon(1e-6);

        final LinePath path = LinePath.fromVertexLoop(Arrays.asList(
                Vector2D.of(-4, 0),
                Vector2D.of(-2, -3),
                Vector2D.of(2, -3),
                Vector2D.of(4, 0),
                Vector2D.of(2, 3),
                Vector2D.of(-2, 3)
            ), precision);

        final RegionBSPTree2D tree = RegionBSPTree2D.partitionedRegionBuilder()
                .insertAxisAlignedGrid(path.getBounds(), 1, precision)
                .insertBoundaries(path)
                .build();

        svgWriter.write(tree, new File(outputFolder, "hex-partitioned.svg"));
    }

public static void main(final String[] args) {
        final File outputFolder = new File(args.length > 0 ? args[0] : ".");
        final BSPTreeSVGWriter svgWriter = new BSPTreeSVGWriter(Bounds2D.from(Vector2D.of(-8, -8), Vector2D.of(8, 8)));

        final Map<RegionNode2D, String> nodeNames = new HashMap<>();
        int cutCount = -1;

        // create a precision context for floating point comparisons
        final Precision.DoubleEquivalence precision = Precision.doubleEquivalenceOfEpsilon(1e-6);

        // construct an empty tree
        final RegionBSPTree2D tree = RegionBSPTree2D.empty();

        final Line rootCut = Lines.fromPointAndDirection(Vector2D.ZERO, Vector2D.Unit.PLUS_X, precision);
        final RegionNode2D a = tree.getRoot();

        nodeNames.put(a, "a");
        svgWriter.write(tree, nodeNames, new File(outputFolder, String.format(OUTPUT_FILE_FORMAT, ++cutCount)));

        // add a single cut
        a.cut(rootCut);

        final RegionNode2D b = a.getMinus();
        final RegionNode2D c = a.getPlus();

        nodeNames.put(b, "b");
        nodeNames.put(c, "c");
        svgWriter.write(tree, nodeNames, new File(outputFolder, String.format(OUTPUT_FILE_FORMAT, ++cutCount)));

        // add another cut
        b.insertCut(Lines.fromPoints(Vector2D.of(1, 0), Vector2D.of(-1, 1), precision));

        final RegionNode2D d = b.getMinus();
        final RegionNode2D e = b.getPlus();

        nodeNames.put(d, "d");
        nodeNames.put(e, "e");
        svgWriter.write(tree, nodeNames, new File(outputFolder, String.format(OUTPUT_FILE_FORMAT, ++cutCount)));

        d.insertCut(Lines.fromPointAndDirection(Vector2D.of(-5, 1), Vector2D.Unit.MINUS_Y, precision));

        final RegionNode2D f = d.getMinus();
        final RegionNode2D g = d.getPlus();

        nodeNames.put(f, "f");
        nodeNames.put(g, "g");
        svgWriter.write(tree, nodeNames, new File(outputFolder, String.format(OUTPUT_FILE_FORMAT, ++cutCount)));

        // other side
        c.insertCut(Lines.fromPoints(Vector2D.of(-1, 0), Vector2D.of(1, -1), precision));

        final RegionNode2D h = c.getMinus();
        final RegionNode2D i = c.getPlus();

        nodeNames.put(h, "h");
        nodeNames.put(i, "i");
        svgWriter.write(tree, nodeNames, new File(outputFolder, String.format(OUTPUT_FILE_FORMAT, ++cutCount)));

        h.insertCut(Lines.fromPointAndDirection(Vector2D.of(5, -1), Vector2D.Unit.PLUS_Y, precision));

        final RegionNode2D j = h.getMinus();
        final RegionNode2D k = h.getPlus();

        nodeNames.put(j, "j");
        nodeNames.put(k, "k");
        svgWriter.write(tree, nodeNames, new File(outputFolder, String.format(OUTPUT_FILE_FORMAT, ++cutCount)));
    }

public static void main(final String[] args) {
        final File outputFolder = new File(args.length > 0 ? args[0] : ".");
        final BSPTreeSVGWriter svgWriter = new BSPTreeSVGWriter(Bounds2D.from(Vector2D.of(-8, -8), Vector2D.of(8, 8)));

        final Map<RegionNode2D, String> nodeNames = new HashMap<>();
        int cutCount = 0;

        // create a precision context for floating point comparisons
        final Precision.DoubleEquivalence precision = Precision.doubleEquivalenceOfEpsilon(1e-6);

        // construct an empty tree
        final RegionBSPTree2D tree = RegionBSPTree2D.empty();

        final Segment firstBoundary = Lines.segmentFromPoints(Vector2D.of(-5, 0), Vector2D.of(-1, 0), precision);
        tree.insert(firstBoundary);

        final RegionNode2D a = tree.getRoot();
        final RegionNode2D b = a.getMinus();
        final RegionNode2D c = a.getPlus();

        nodeNames.put(a, "a");
        nodeNames.put(b, "b");
        nodeNames.put(c, "c");
        svgWriter.write(tree, nodeNames, new File(outputFolder, String.format(OUTPUT_FILE_FORMAT, ++cutCount)));

        tree.insert(Lines.segmentFromPoints(Vector2D.of(1, 0), Vector2D.of(-5, 3), precision));
        tree.insert(Lines.segmentFromPoints(Vector2D.of(-5, 3), Vector2D.of(-5, 0), precision));

        final RegionNode2D d = b.getMinus();
        final RegionNode2D e = b.getPlus();
        final RegionNode2D f = d.getMinus();
        final RegionNode2D g = d.getPlus();

        nodeNames.put(d, "d");
        nodeNames.put(e, "e");
        nodeNames.put(f, "f");
        nodeNames.put(g, "g");
        svgWriter.write(tree, nodeNames, new File(outputFolder, String.format(OUTPUT_FILE_FORMAT, ++cutCount)));

        final LinePath path = LinePath.fromVertices(Arrays.asList(
                Vector2D.of(-1, 0),
                Vector2D.of(5, -3),
                Vector2D.of(5, 0),
                Vector2D.of(1, 0)), precision);
        tree.insert(path);

        final RegionNode2D h = c.getMinus();
        final RegionNode2D i = c.getPlus();
        final RegionNode2D j = h.getMinus();
        final RegionNode2D k = h.getPlus();

        nodeNames.put(h, "h");
        nodeNames.put(i, "i");
        nodeNames.put(j, "j");
        nodeNames.put(k, "k");
        svgWriter.write(tree, nodeNames, new File(outputFolder, String.format(OUTPUT_FILE_FORMAT, ++cutCount)));
    }

public static void main(final String[] args) {
        final File outputFolder = new File(args.length > 0 ? args[0] : ".");
        final BSPTreeSVGWriter svgWriter = new BSPTreeSVGWriter(Bounds2D.from(Vector2D.of(-8, -8), Vector2D.of(8, 8)));

        final Precision.DoubleEquivalence precision = Precision.doubleEquivalenceOfEpsilon(1e-6);

        final RegionBSPTree2D tree = RegionBSPTree2D.empty();

        tree.insert(Lines.fromPointAndDirection(Vector2D.ZERO, Vector2D.Unit.PLUS_X, precision).span(),
                RegionCutRule.INHERIT);

        svgWriter.write(tree, new File(outputFolder, "hex-struct-0.svg"));

        final LinePath path = LinePath.fromVertexLoop(Arrays.asList(
                    Vector2D.of(-4, 0),
                    Vector2D.of(-2, -3),
                    Vector2D.of(2, -3),
                    Vector2D.of(4, 0),
                    Vector2D.of(2, 3),
                    Vector2D.of(-2, 3)
                ), precision);
        tree.insert(path);

        svgWriter.write(tree, new File(outputFolder, "hex-struct-1.svg"));
    }

docstring:
/** Build a teapot as a {@link RegionBSPTree3D}.
     * @return teapot as a BSP tree
     */

method_definition:
public RegionBSPTree3D buildTeapot() {
        return buildTeapot(null);
    }

public RegionBSPTree3D buildTeapot(final Map<String, RegionBSPTree3D> debugOutputs) {
        // build the parts
        final RegionBSPTree3D body = buildBody(1);
        final RegionBSPTree3D lid = buildLid(body);
        final RegionBSPTree3D handle = buildHandle();
        final RegionBSPTree3D spout = buildSpout(1);

        // combine into the final region
        final RegionBSPTree3D teapot = RegionBSPTree3D.empty();
        teapot.union(body, lid);
        teapot.union(handle);
        teapot.union(spout);

        // subtract scaled-down versions of the body and spout to
        // create the hollow interior
        teapot.difference(buildBody(0.9));
        teapot.difference(buildSpout(0.8));

        // add debug outputs if needed
        if (debugOutputs != null) {
            debugOutputs.put(BODY_NAME, body);
            debugOutputs.put(LID_NAME, lid);
            debugOutputs.put(HANDLE_NAME, handle);
            debugOutputs.put(SPOUT_NAME, spout);
        }

        return teapot;
    }

public Map<String, RegionBSPTree3D> buildSeparatedTeapot() {
        // construct the single-piece teapot
        final RegionBSPTree3D teapot = buildTeapot();

        // create a region to extract the lid
        final AffineTransformMatrix3D innerCylinderTransform = AffineTransformMatrix3D.createScale(0.4, 0.4, 1)
                .translate(0, 0, 0.5);
        final RegionBSPTree3D innerCylinder = buildUnitCylinderMesh(1, 20, innerCylinderTransform).toTree();

        final AffineTransformMatrix3D outerCylinderTransform = AffineTransformMatrix3D.createScale(0.5, 0.5, 10);
        final RegionBSPTree3D outerCylinder = buildUnitCylinderMesh(1, 20, outerCylinderTransform).toTree();

        final Plane step = Planes.fromPointAndNormal(Vector3D.of(0, 0, 0.63), Vector3D.Unit.MINUS_Z, precision);

        final RegionBSPTree3D extractor = RegionBSPTree3D.from(Arrays.asList(step.span()));
        extractor.union(innerCylinder);
        extractor.intersection(outerCylinder);

        // extract the lid
        final RegionBSPTree3D lid = RegionBSPTree3D.empty();
        lid.intersection(teapot, extractor);

        // remove the lid from the body
        final RegionBSPTree3D body = RegionBSPTree3D.empty();
        body.difference(teapot, extractor);

        // build the output
        final Map<String, RegionBSPTree3D> result = new LinkedHashMap<>();
        result.put(LID_NAME, lid);
        result.put(BODY_NAME, body);

        return result;
    }

private RegionBSPTree3D buildBody(final double initialRadius) {
        // construct a BSP tree sphere approximation
        final Sphere sphere = Sphere.from(Vector3D.ZERO, initialRadius, precision);
        final RegionBSPTree3D body = sphere.toTree(4);

        // squash it a little bit along the z-axis
        final AffineTransformMatrix3D t = AffineTransformMatrix3D.createScale(1, 1, 0.75);
        body.transform(t);

        // cut off part of the bottom to make it flat
        final Plane bottomPlane = Planes.fromPointAndNormal(
                Vector3D.of(0, 0, -0.6 * initialRadius),
                Vector3D.Unit.PLUS_Z,
                precision);
        final PlaneConvexSubset bottom = bottomPlane.span();
        body.difference(RegionBSPTree3D.from(Arrays.asList(bottom)));

        return body;
    }

private RegionBSPTree3D buildLid(final RegionBSPTree3D body) {
        // make a copy of the body so that we match its curve exactly
        final RegionBSPTree3D lid = body.copy();

        // translate the lid to be above the body
        final AffineTransformMatrix3D t = AffineTransformMatrix3D.createTranslation(0, 0, 0.03);
        lid.transform(t);

        // intersect the translated body with a cylinder
        final TriangleMesh cylinder =
                buildUnitCylinderMesh(1, 20, AffineTransformMatrix3D.createScale(0.5, 0.5, 10));
        lid.intersection(cylinder.toTree());

        // add a small squashed sphere on top; use the bounds of the top in order to place
        // the sphere at the correct position
        final Sphere sphere = Sphere.from(Vector3D.of(0, 0, 0), 0.15, precision);
        final RegionBSPTree3D sphereTree = sphere.toTree(2);

        final Bounds3D lidBounds = lid.getBounds();
        final double sphereZ = lidBounds.getMax().getZ() + 0.075;
        sphereTree.transform(AffineTransformMatrix3D.createScale(1, 1, 0.75)
                .translate(0, 0, sphereZ));

        // make the small sphere a part of the top
        lid.union(sphereTree);

        return lid;
    }

docstring:
/** Build the handle of the teapot.
     * @return teapot handle
     */

method_definition:
private RegionBSPTree3D buildHandle() {
        final double handleRadius = 0.1;
        final double height = 1 - (2 * handleRadius);

        final AffineTransformMatrix3D scale =
                AffineTransformMatrix3D.createScale(handleRadius, handleRadius, height);

        final QuaternionRotation startRotation =
                QuaternionRotation.fromAxisAngle(Vector3D.Unit.PLUS_Y, -Angle.PI_OVER_TWO);
        final QuaternionRotation endRotation =
                QuaternionRotation.fromAxisAngle(Vector3D.Unit.PLUS_Y, Angle.PI_OVER_TWO);
        final DoubleFunction<QuaternionRotation> slerp = startRotation.slerp(endRotation);

        final Vector3D curveCenter = Vector3D.of(0.5 * height, 0, 0);

        final AffineTransformMatrix3D translation =
                AffineTransformMatrix3D.createTranslation(Vector3D.of(-1.38, 0, 0));

        final UnaryOperator<Vector3D> vertexTransform = v -> {
            final double t = v.getZ();

            final Vector3D scaled = scale.apply(v);

            final QuaternionRotation rot = slerp.apply(t);
            final AffineTransformMatrix3D mat = AffineTransformMatrix3D.createRotation(curveCenter, rot);

            final Vector3D rotated = mat.apply(Vector3D.of(scaled.getX(), scaled.getY(), 0));

            final Vector3D result = (t > 0 && t < 1) ?
                    rotated :
                    rotated.add(Vector3D.Unit.PLUS_X);

            return translation.apply(result);
        };

        return buildUnitCylinderMesh(10, 14, vertexTransform).toTree();
    }

private RegionBSPTree3D buildSpout(final double initialRadius) {
        final Vector2D baseScale = Vector2D.of(0.4, 0.2).multiply(initialRadius);
        final Vector2D topScale = baseScale.multiply(0.6);
        final double shearZ = 0.9;

        final AffineTransformMatrix3D translation =
                AffineTransformMatrix3D.createTranslation(Vector3D.of(0.25, 0, -0.4));

        final UnaryOperator<Vector3D> vertexTransform = v -> {
            final Vector2D scale = baseScale.lerp(topScale, v.getZ());

            final Vector3D tv = Vector3D.of(
                        (v.getX() * scale.getX()) + (v.getZ() * shearZ),
                        v.getY() * scale.getY(),
                        v.getZ()
                    );

            return translation.apply(tv);
        };

        return buildUnitCylinderMesh(1, 14, vertexTransform).toTree();
    }

private TriangleMesh buildUnitCylinderMesh(final int segments, final int circleVertexCount,
            final UnaryOperator<Vector3D> vertexTransform) {

        final SimpleTriangleMesh.Builder builder = SimpleTriangleMesh.builder(precision);

        // add the cylinder vertices
        final double zDelta = 1.0 / segments;
        double zValue;

        final double azDelta = Angle.TWO_PI / circleVertexCount;
        double az;

        Vector3D vertex;
        for (int i = 0; i <= segments; ++i) {
            zValue = i * zDelta;

            for (int v = 0; v < circleVertexCount; ++v) {
                az = v * azDelta;

                vertex = Vector3D.of(
                        Math.cos(az),
                        Math.sin(az),
                        zValue);
                builder.addVertex(vertexTransform.apply(vertex));
            }
        }

        // add the bottom faces using a triangle fan, making sure
        // that the triangles are oriented so that the face normal
        // points down
        for (int i = 1; i < circleVertexCount - 1; ++i) {
            builder.addFace(0, i + 1, i);
        }

        // add the side faces
        int circleStart;
        int v1;
        int v2;
        int v3;
        int v4;
        for (int s = 0; s < segments; ++s) {
            circleStart = s * circleVertexCount;

            for (int i = 0; i < circleVertexCount; ++i) {
                v1 = i + circleStart;
                v2 = ((i + 1) % circleVertexCount) + circleStart;
                v3 = v2 + circleVertexCount;
                v4 = v1 + circleVertexCount;

                builder
                    .addFace(v1, v2, v3)
                    .addFace(v1, v3, v4);
            }
        }

        // add the top faces using a triangle fan
        final int lastCircleStart = circleVertexCount * segments;
        for (int i = 1 + lastCircleStart; i < builder.getVertexCount() - 1; ++i) {
            builder.addFace(lastCircleStart, i, i + 1);
        }

        return builder.build();
    }

public static void main(final String[] args) throws IOException {
        if (args.length < 1) {
            throw new IllegalArgumentException("Output file argument is required");
        }

        final Path outputFile = Paths.get(args[0]);
        final Precision.DoubleEquivalence precision = Precision.doubleEquivalenceOfEpsilon(1e-10);

        final TeapotBuilder builder = new TeapotBuilder(precision);

        final Map<String, RegionBSPTree3D> debugOutputs = new HashMap<>();

        final RegionBSPTree3D teapot = builder.buildTeapot(debugOutputs);

        IO3D.write(teapot, outputFile);

        if (args.length > 1) {
            // write additional files to the debug dir
            final Path debugDir = Paths.get(args[1]);
            Files.createDirectories(debugDir);

            // build and write teapot components
            final Map<String, RegionBSPTree3D> partMap = builder.buildSeparatedTeapot();
            try (ObjWriter writer = new ObjWriter(Files.newBufferedWriter(debugDir.resolve("separated-teapot.obj")))) {

                for (Map.Entry<String, RegionBSPTree3D> entry : partMap.entrySet()) {
                    writer.writeObjectName(entry.getKey());
                    writer.writeBoundaries(entry.getValue());
                }
            }

            // write debug outputs
            for (Map.Entry<String, RegionBSPTree3D> entry : debugOutputs.entrySet()) {
                IO3D.write(entry.getValue(), debugDir.resolve(entry.getKey() + ".stl"));
            }
        }
    }

